    setNotifications((prev) =>
      prev.map((n) => (n._id === id || n.id === id ? { ...n, read: true } : n))
    )
    try {
      await notificationService.markAsRead(id)
    } catch {}

    if (link) {
      setNotifOpen(false)
      navigate(link)
    }
  }

  const handleMarkAllRead = async () => {
