            keyDecisions: ['Approved #2563EB primary enterprise palette'],
            actionItems: [],
            status: 'completed',
          },
        ],
        total: 2,
        page: 1,
        totalPages: 1,
      })
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
    fetchHistory()
  }, [searchQuery, statusFilter, sortBy, page])

  return (
    <div className="max-w-6xl mx-auto space-y-6 animate-fade-in pb-12">
      {/* Top Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-4 border-b border-[#EAECF0]">
        <div>
          <h1 className="font-heading text-2xl font-bold text-[#101828] flex items-center gap-2.5">
            <History className="w-6 h-6 text-[#2563EB]" />
            Meeting History & Archive
          </h1>
          <p className="text-xs text-[#667085] mt-0.5">
            Search, filter, and inspect past collaboration recordings, transcripts, and AI-generated minutes.
          </p>
        </div>

        <div className="relative w-full sm:w-72">
          <Search className="w-3.5 h-3.5 text-[#98A2B3] absolute left-3 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            placeholder="Search title, host, summary, or room..."
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value)
              setPage(1)
            }}
            className="w-full pl-9 pr-3 py-1.5 rounded-lg border border-[#D0D5DD] bg-white text-xs text-[#101828] placeholder-[#98A2B3] focus:outline-none focus:border-[#2563EB]"
          />
        </div>
      </div>

      {/* Filter and Sort Toolbar */}
      <div className="flex flex-wrap items-center justify-between gap-3 bg-white p-3 rounded-xl border border-[#EAECF0] text-xs">
        {/* Status filters */}
        <div className="flex items-center gap-1.5">
          <span className="text-[#667085] font-medium mr-1 flex items-center gap-1">
            <Filter className="w-3.5 h-3.5 text-[#98A2B3]" /> Status:
          </span>
          {(['all', 'completed', 'scheduled', 'cancelled'] as const).map((st) => (
            <button
              key={st}
              onClick={() => {
                setStatusFilter(st)
                setPage(1)
              }}
              className={`px-2.5 py-1 rounded-md capitalize font-medium transition-colors ${
                statusFilter === st
                  ? 'bg-[#101828] text-white'
                  : 'bg-[#F8FAFC] border border-[#EAECF0] text-[#475467] hover:bg-[#F2F4F7]'
              }`}
            >
              {st}
            </button>
          ))}
        </div>

        {/* Sort selector */}
        <div className="flex items-center gap-2">
          <span className="text-[#667085] font-medium flex items-center gap-1">
            <ArrowUpDown className="w-3.5 h-3.5 text-[#98A2B3]" /> Sort by:
          </span>
          <select
            value={sortBy}
            onChange={(e) => {
              setSortBy(e.target.value as any)
              setPage(1)
            }}
            className="rounded-lg border border-[#D0D5DD] bg-white px-2.5 py-1 text-xs text-[#101828] focus:border-[#2563EB] focus:outline-none"
          >
            <option value="date_desc">Newest First</option>
            <option value="date_asc">Oldest First</option>
            <option value="duration">Longest Duration</option>
          </select>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* Left List of Meetings with Pagination */}
        <div className="lg:col-span-5 space-y-3">
          {isLoading ? (
            <div className="p-8 text-center text-xs text-[#667085]">
              Loading meeting archive...
            </div>
          ) : historyData.meetings.length === 0 ? (
            <Card className="p-8 text-center space-y-2">
              <Video className="w-8 h-8 text-[#98A2B3] mx-auto" />
              <div className="text-sm font-semibold text-[#101828]">No Meetings Found</div>
              <div className="text-xs text-[#667085]">
                Adjust your search or filter criteria to see archived sessions.
              </div>
            </Card>
          ) : (
            historyData.meetings.map((m: any) => {
              const isSelected = selectedMeeting?.roomId === m.roomId
              return (
                <div
                  key={m.roomId || m._id}
                  onClick={() => setSelectedMeeting(m)}
                  className={`p-4 rounded-xl border cursor-pointer transition-all ${
                    isSelected
                      ? 'bg-[#EFF8FF] border-[#2563EB] shadow-subtle'
                      : 'bg-white border-[#EAECF0] hover:border-[#D0D5DD] hover:bg-[#F8FAFC]'
                  }`}
                >
                  <div className="flex items-center justify-between mb-1.5">
                    <span className="font-semibold text-sm text-[#101828]">
                      {m.title || m.roomId}
                    </span>
                    <Badge
                      variant={
                        m.status === 'completed'
                          ? 'success'
                          : m.status === 'cancelled'
                          ? 'error'
                          : 'primary'
                      }
                      size="sm"
                    >
                      {m.status || 'completed'}
                    </Badge>
                  </div>

                  <p className="text-xs text-[#667085] line-clamp-2 leading-relaxed">
                    {m.summary || m.description || 'Sprint session with active multi-user discussions.'}
                  </p>

                  <div className="flex flex-wrap items-center gap-3 text-[11px] text-[#667085] mt-3 pt-2 border-t border-[#EAECF0]">
                    <span className="flex items-center gap-1">
                      <Users className="w-3.5 h-3.5 text-[#98A2B3]" /> {m.hostName || 'Host'}
                    </span>
                    <span>•</span>
                    <span className="flex items-center gap-1">
                      <Clock className="w-3.5 h-3.5 text-[#98A2B3]" /> {m.durationMinutes || 42} mins
                    </span>
                    <span>•</span>
                    <span className="flex items-center gap-1">
                      <Calendar className="w-3.5 h-3.5 text-[#98A2B3]" />
                      {new Date(m.createdAt || Date.now()).toLocaleDateString()}
                    </span>
                  </div>
                </div>
              )
            })
          )}

          {/* Pagination Controls */}
          {historyData.totalPages > 1 && (
            <div className="flex items-center justify-between pt-2 px-1 text-xs text-[#667085]">
              <span>
                Page {historyData.page} of {historyData.totalPages} ({historyData.total} total)
              </span>
              <div className="flex items-center gap-1">
                <Button
                  variant="outline"
                  size="sm"
                  disabled={page <= 1}
                  onClick={() => setPage((p) => Math.max(1, p - 1))}
                  icon={<ChevronLeft className="w-3.5 h-3.5" />}
                >
                  Prev
                </Button>
                <Button
                  variant="outline"
                  size="sm"
                  disabled={page >= historyData.totalPages}
                  onClick={() => setPage((p) => p + 1)}
                  iconRight={<ChevronRight className="w-3.5 h-3.5" />}
                >
                  Next
                </Button>
              </div>
            </div>
          )}
        </div>

        {/* Right Detail Pane */}
        <div className="lg:col-span-7">
          {selectedMeeting ? (
            <Card className="space-y-6">
              {/* Top Header */}
              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-[#EAECF0] pb-4">
                <div>
                  <h2 className="font-heading text-lg font-bold text-[#101828]">
                    {selectedMeeting.title || selectedMeeting.roomId}
                  </h2>
                  <div className="flex flex-wrap items-center gap-3 text-xs text-[#667085] mt-1">
                    <span>Host: <strong className="text-[#101828]">{selectedMeeting.hostName || 'Host'}</strong></span>
                    <span>•</span>
                    <span>Duration: <strong>{selectedMeeting.durationMinutes || 42} mins</strong></span>
                    <span>•</span>
                    <span>Room: <strong className="font-mono text-[#2563EB]">{selectedMeeting.roomId}</strong></span>
                  </div>
                </div>

                <div className="flex items-center gap-2">
                  <Link to={`/app/insights?meetingId=${selectedMeeting.roomId}`}>
                    <Button variant="secondary" size="sm" icon={<Sparkles className="w-3.5 h-3.5 text-[#2563EB]" />}>
                      AI Insights
                    </Button>
                  </Link>

                  <Link to={`/room/${selectedMeeting.roomId}`}>
                    <Button variant="primary" size="sm" icon={<Video className="w-3.5 h-3.5" />}>
                      Rejoin Room
                    </Button>
                  </Link>
                </div>
              </div>

              {/* Participants Roster */}
              {selectedMeeting.participantsList && selectedMeeting.participantsList.length > 0 && (
                <div className="space-y-1.5">
                  <div className="text-xs font-semibold uppercase tracking-wider text-[#667085] flex items-center gap-1.5">
                    <Users className="w-3.5 h-3.5 text-[#2563EB]" /> Participants ({selectedMeeting.participantsList.length})
                  </div>
                  <div className="flex flex-wrap gap-1.5 text-xs">
                    {selectedMeeting.participantsList.map((p: string, idx: number) => (
                      <span
                        key={idx}
                        className="px-2.5 py-1 rounded-md bg-[#F8FAFC] border border-[#EAECF0] text-[#344054] font-medium"
                      >
                        {p}
                      </span>
                    ))}
                  </div>
                </div>
              )}

              {/* Cloud Recording Player / Download Link */}
              {selectedMeeting.recordingUrl && (
                <div className="p-3.5 rounded-xl border border-[#B2DDFF] bg-[#EFF8FF] flex items-center justify-between text-xs">
                  <div className="flex items-center gap-3">
                    <div className="w-8 h-8 rounded-lg bg-[#2563EB] text-white flex items-center justify-center">
                      <Film className="w-4 h-4" />
                    </div>
                    <div>
                      <div className="font-semibold text-[#175CD3]">Cloud Session Recording</div>
                      <div className="text-[11px] text-[#2563EB]">Persisted to S3/R2 Cloud Object Storage</div>
                    </div>
                  </div>
                  <a
                    href={selectedMeeting.recordingUrl}
                    target="_blank"
                    rel="noopener noreferrer"
                  >
                    <Button variant="primary" size="sm" icon={<Play className="w-3 h-3" />}>
                      Watch Recording
                    </Button>
                  </a>
                </div>
              )}

              {/* Spoken Transcript Preview */}
              {selectedMeeting.transcriptSnippet && (
                <div className="space-y-2">
                  <div className="text-xs font-semibold uppercase tracking-wider text-[#667085] flex items-center gap-1.5">
                    <Quote className="w-3.5 h-3.5 text-[#2563EB]" />
                    Transcript Excerpt
                  </div>
                  <div className="p-3 rounded-xl bg-[#F8FAFC] border border-[#EAECF0] text-xs text-[#475467] italic leading-relaxed">
                    "{selectedMeeting.transcriptSnippet}"
                  </div>
                </div>
              )}

              {/* Executive Summary */}
              <div className="space-y-2">
                <div className="text-xs font-semibold uppercase tracking-wider text-[#667085] flex items-center gap-1.5">
                  <FileText className="w-3.5 h-3.5 text-[#2563EB]" />
                  Executive Summary
                </div>
                <div className="p-4 rounded-xl bg-[#F8FAFC] border border-[#EAECF0] text-xs text-[#344054] leading-relaxed">
                  {selectedMeeting.summary || 'No summary recorded for this session.'}
                </div>
              </div>

              {/* Key Decisions */}
              {selectedMeeting.keyDecisions && selectedMeeting.keyDecisions.length > 0 && (
                <div className="space-y-2">
                  <div className="text-xs font-semibold uppercase tracking-wider text-[#12B76A] flex items-center gap-1.5">
                    <Shield className="w-4 h-4" />
                    Key Decisions
                  </div>
                  <ul className="space-y-1.5">
                    {selectedMeeting.keyDecisions.map((decision: string, idx: number) => (
                      <li
                        key={idx}
                        className="p-3 rounded-xl bg-white border border-[#EAECF0] text-xs text-[#344054] flex items-start gap-2"
                      >
                        <span className="text-[#12B76A] font-bold mt-0.5">•</span>
                        <span>{decision}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {/* Action items */}
              {selectedMeeting.actionItems && selectedMeeting.actionItems.length > 0 && (
                <div className="space-y-2">
                  <div className="text-xs font-semibold uppercase tracking-wider text-[#F79009] flex items-center gap-1.5">
                    <ListTodo className="w-4 h-4" />
                    Action Items ({selectedMeeting.actionItems.length})
                  </div>
                  <div className="space-y-1.5">
                    {selectedMeeting.actionItems.map((item: any, idx: number) => (
                      <div
                        key={item.id || idx}
                        className={`p-3 rounded-xl border text-xs flex items-start gap-2.5 ${
                          item.completed
                            ? 'bg-[#F8FAFC] border-[#EAECF0] text-[#98A2B3] line-through'
                            : 'bg-white border-[#EAECF0] text-[#101828]'
                        }`}
                      >
                        <CheckCircle2
                          className={`w-4 h-4 shrink-0 mt-0.5 ${
                            item.completed ? 'text-[#12B76A]' : 'text-[#D0D5DD]'
                          }`}
                        />
                        <div className="space-y-0.5">
                          <div>{item.text || item.title}</div>
                          <div className="text-[10px] text-[#667085]">
                            Assignee: <span className="text-[#2563EB] font-medium">{item.assignee || item.assigneeName || 'Unassigned'}</span>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </Card>
          ) : (
            <Card className="py-16 text-center space-y-3">
              <FileText className="w-10 h-10 text-[#98A2B3] mx-auto" />
              <div className="text-sm font-semibold text-[#101828]">Select a Meeting Session</div>
              <div className="text-xs text-[#667085] max-w-sm mx-auto">
                Click on any session in the list to inspect its executive summary, recording, key decisions, and action items.
              </div>
            </Card>
          )}
        </div>
      </div>
    </div>
  )
}

import React, { useEffect, useState, useRef } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import {
  Mic,
  MicOff,
  Video as VideoIcon,
  VideoOff,
  MonitorUp,
  MessageSquare,
  Sparkles,
  PhoneOff,
  Send,
  Users,
  Copy,
  CheckCircle2,
  Check,
  Captions,
  Loader2,
  ListTodo,
  Info,
  Shield,
  FileText,
} from 'lucide-react'
import { Button } from '../components/ui/Button'
import { Badge } from '../components/ui/Badge'
import { useSocket } from '../hooks/useSocket'
import { useWebRTC } from '../hooks/useWebRTC'
import { useSpeechRecognition } from '../hooks/useSpeechRecognition'
import { useMeetingStore } from '../stores/meetingStore'
import { useAuthStore } from '../stores/authStore'
import { aiService } from '../services/aiService'
import { meetingService } from '../services/meetingService'
import { ChatMessage } from '../types'

export const MeetingPage: React.FC = () => {
  const { roomId = 'sprint-room' } = useParams<{ roomId: string }>()
  const navigate = useNavigate()
  const { socket, isConnected } = useSocket()
  const user = useAuthStore((s) => s.user)

  // Store state
  const {
    isMicOn,
    isCamOn,
    isScreenSharing,
    isTranscribing,
    activeSideTab,
    messages,
    transcripts,
    liveSubtitle,
    liveSubtitleSpeaker,
    actionItems,
    participantsCount,
    setRoomId,
    toggleMic,
    toggleCam,
    toggleTranscribing,
    setActiveSideTab,
    addMessage,
    setActionItems,
    toggleActionItem,
    setParticipantsCount,
    resetMeetingState,
  } = useMeetingStore()

  // Local state
  const [copiedLink, setCopiedLink] = useState(false)
  const [messageInput, setMessageInput] = useState('')
  const [isGeneratingAi, setIsGeneratingAi] = useState(false)
  const [aiSummary, setAiSummary] = useState<string>('')
  const [keyDecisions, setKeyDecisions] = useState<string[]>([])
  const [isSavingMeeting, setIsSavingMeeting] = useState(false)

  // WebRTC & Speech Recognition Hooks
  const {
    localStream,
    screenStream,
    localVideoRef,
    screenVideoRef,
    deviceError,
    initMedia,
    toggleScreenShare,
  } = useWebRTC()

  useSpeechRecognition(roomId)

  const chatEndRef = useRef<HTMLDivElement | null>(null)

  // Initialize room and local media
  useEffect(() => {
    setRoomId(roomId)
    initMedia()

    if (socket && roomId) {
      socket.emit('join-room', {
        roomId,
        userName: user.name,
        userId: user.id,
      })

      socket.on('user-joined', (data: { userName: string }) => {
        addMessage({
          id: `sys_${Date.now()}`,
          sender: 'IntellMeet Assistant',
          text: `${data.userName} joined the room.`,
          isSystem: true,
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        })
        setParticipantsCount(participantsCount + 1)
      })

      socket.on('receive-message', (msg: ChatMessage) => {
        addMessage(msg)
      })

      socket.on('user-left', (data: { userName: string }) => {
        addMessage({
          id: `sys_${Date.now()}`,
          sender: 'IntellMeet Assistant',
          text: `${data.userName || 'A participant'} left the meeting.`,
          isSystem: true,
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
        })
      })
    }

    return () => {
      if (socket) {
        socket.emit('leave-room', { roomId })
        socket.off('user-joined')
        socket.off('receive-message')
        socket.off('user-left')
      }
      resetMeetingState()
    }
  }, [roomId, socket, user.name, user.id])

  // Scroll to bottom on new chat messages
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' })
  }, [messages])

  // Send Chat message
  const handleSendMessage = (e: React.FormEvent) => {
    e.preventDefault()
    if (!messageInput.trim() || !socket) return

    const newMsg: ChatMessage = {
      id: `msg_${Date.now()}`,
      sender: user.name,
      text: messageInput.trim(),
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
    }

    socket.emit('send-message', {
      roomId,
      message: newMsg,
    })

    setMessageInput('')
  }

  // Copy meeting invite link
  const handleCopyInvite = () => {
    navigator.clipboard.writeText(window.location.href)
    setCopiedLink(true)
    setTimeout(() => setCopiedLink(false), 2500)
  }

  // Autonomous AI Summarization Trigger
  const handleGenerateSummary = async () => {
    setIsGeneratingAi(true)
    try {
      const result = await aiService.summarize({
        roomName: roomId,
        transcript: transcripts,
        messages: messages,
      })

      const summaryObj = result.summary
      const summaryText =
        typeof summaryObj === 'string'
          ? summaryObj
          : summaryObj?.meetingOverview || ''
      const decisions = summaryObj?.importantDecisions || []
      const items = (result.actionItems || []).map((item, idx) => ({
        id: item.id || `ai_item_${idx}_${Date.now()}`,
        text: item.title || (item as any).text || '',
        assignee: item.assignee || 'Unassigned',
        completed: item.status === 'completed',
        priority: item.priority || 'medium',
      }))

      setAiSummary(summaryText)
      setKeyDecisions(decisions)
      setActionItems(items)
      setActiveSideTab('ai')
    } catch (err: unknown) {
      console.error('AI summary error:', err)
    } finally {
      setIsGeneratingAi(false)
    }
  }

  // End Meeting & Save to MongoDB
  const handleEndMeeting = async () => {
    setIsSavingMeeting(true)
    try {
      await meetingService.saveMeeting({
        roomId,
        title: `Sprint: ${roomId}`,
        hostName: user.name,
        participants: [user.name],
        participantsList: [user.name],
        summary: aiSummary || 'Session ended with live collaboration.',
        keyDecisions,
        actionItems,
      })
      navigate('/history')
    } catch {
      navigate('/history')
    } finally {
      setIsSavingMeeting(false)
    }
  }

  return (
    <div className="h-[calc(100vh-6.5rem)] flex flex-col gap-4">
      {/* Top Header Bar inside room */}
      <div className="flex items-center justify-between bg-surface-900/90 border border-slate-800 px-5 py-3 rounded-2xl shrink-0">
        <div className="flex items-center gap-3">
          <Badge variant="purple" className="text-xs font-mono">
            Room: {roomId}
          </Badge>
          <div className="hidden sm:flex items-center gap-2 text-xs text-slate-400">
            <Users className="w-3.5 h-3.5 text-brand-400" />
            <span>{participantsCount} in room</span>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            icon={copiedLink ? <Check className="w-4 h-4 text-emerald-400" /> : <Copy className="w-4 h-4" />}
            onClick={handleCopyInvite}
          >
            {copiedLink ? 'Link Copied!' : 'Copy Invite'}
          </Button>

          <Button
            variant="primary"
            size="sm"
            icon={isGeneratingAi ? <Loader2 className="w-4 h-4 animate-spin text-white" /> : <Sparkles className="w-4 h-4 text-cyan-300" />}
            disabled={isGeneratingAi}
            onClick={handleGenerateSummary}
          >
            {isGeneratingAi ? 'Summarizing...' : 'Generate AI Minutes'}
          </Button>
        </div>
      </div>

      {/* Main Center Area: Video Stage + Side Drawer */}
      <div className="flex-1 flex gap-4 min-h-0">
        {/* Video Canvas Stage */}
        <div className="flex-1 bg-surface-950 border border-slate-800/80 rounded-3xl relative overflow-hidden flex flex-col justify-between p-4 shadow-2xl">
          {/* Main Video Element */}
          <div className="relative flex-1 w-full h-full rounded-2xl overflow-hidden bg-slate-900 flex items-center justify-center">
            {/* Screen Share or Local Webcam */}
            {isScreenSharing ? (
              <video
                ref={screenVideoRef}
                autoPlay
                playsInline
                className="w-full h-full object-contain bg-black"
              />
            ) : isCamOn ? (
              <video
                ref={localVideoRef}
                autoPlay
                playsInline
                muted
                className="w-full h-full object-cover scale-x-[-1]"
              />
            ) : (
              <div className="flex flex-col items-center gap-3 text-slate-500">
                <div className="w-20 h-20 rounded-full bg-slate-800 flex items-center justify-center text-slate-400 font-bold text-2xl">
                  {user.name.charAt(0)}
                </div>
                <div className="text-sm font-medium">{user.name} (Camera Off)</div>
              </div>
            )}

            {/* Device permission note if applicable */}
            {deviceError && (
              <div className="absolute top-4 left-4 right-4 bg-amber-950/90 border border-amber-800/80 p-3 rounded-xl flex items-center gap-2 text-xs text-amber-300 backdrop-blur-md">
                <Info className="w-4 h-4 shrink-0" />
                <span>{deviceError}</span>
              </div>
            )}

            {/* Spoken Subtitle Overlay (Live SpeechRecognition) */}
            {isTranscribing && liveSubtitle && (
              <div className="absolute bottom-6 left-6 right-6 flex justify-center pointer-events-none">
                <div className="max-w-2xl bg-black/80 backdrop-blur-md border border-white/10 px-5 py-2.5 rounded-2xl shadow-2xl text-center space-y-0.5 animate-fade-in">
                  <div className="text-[10px] font-semibold text-cyan-400 uppercase tracking-wider flex items-center justify-center gap-1">
                    <Captions className="w-3 h-3" />
                    {liveSubtitleSpeaker || user.name}
                  </div>
                  <div className="text-sm text-slate-100 font-medium">
                    "{liveSubtitle}"
                  </div>
                </div>
              </div>
            )}

            {/* Video overlay badge: Username */}
            <div className="absolute bottom-4 left-4 bg-slate-900/80 backdrop-blur-sm border border-slate-700/80 px-3 py-1 rounded-xl text-xs font-medium text-slate-200 flex items-center gap-2">
              <span className="w-2 h-2 rounded-full bg-emerald-400" />
              <span>{user.name} (You)</span>
              {!isMicOn && <MicOff className="w-3 h-3 text-rose-400" />}
            </div>
          </div>

          {/* Bottom Floating Conference Control Bar */}
          <div className="mt-4 flex items-center justify-center gap-3">
            {/* Mic Toggle */}
            <Button
              variant={isMicOn ? 'secondary' : 'danger'}
              size="md"
              icon={isMicOn ? <Mic className="w-4 h-4" /> : <MicOff className="w-4 h-4" />}
              onClick={toggleMic}
            >
              {isMicOn ? 'Mute' : 'Unmute'}
            </Button>

            {/* Camera Toggle */}
            <Button
              variant={isCamOn ? 'secondary' : 'danger'}
              size="md"
              icon={isCamOn ? <VideoIcon className="w-4 h-4" /> : <VideoOff className="w-4 h-4" />}
              onClick={toggleCam}
            >
              {isCamOn ? 'Stop Video' : 'Start Video'}
            </Button>

            {/* Screen Share */}
            <Button
              variant={isScreenSharing ? 'primary' : 'secondary'}
              size="md"
              icon={<MonitorUp className="w-4 h-4" />}
              onClick={toggleScreenShare}
            >
              {isScreenSharing ? 'Stop Share' : 'Share Screen'}
            </Button>

            {/* Live Subtitles Toggle */}
            <Button
              variant={isTranscribing ? 'outline' : 'ghost'}
              size="md"
              icon={<Captions className="w-4 h-4 text-cyan-400" />}
              onClick={toggleTranscribing}
            >
              Captions {isTranscribing ? 'ON' : 'OFF'}
            </Button>

            {/* Side Tabs Toggle: Chat vs AI */}
            <Button
              variant={activeSideTab === 'chat' ? 'outline' : 'ghost'}
              size="md"
              icon={<MessageSquare className="w-4 h-4" />}
              onClick={() => setActiveSideTab('chat')}
            >
              Chat
            </Button>

            <Button
              variant={activeSideTab === 'ai' ? 'outline' : 'ghost'}
              size="md"
              icon={<Sparkles className="w-4 h-4 text-brand-400" />}
              onClick={() => setActiveSideTab('ai')}
            >
              AI Minutes
            </Button>

            {/* Leave / End Call */}
            <Button
              variant="danger"
              size="md"
              icon={isSavingMeeting ? <Loader2 className="w-4 h-4 animate-spin" /> : <PhoneOff className="w-4 h-4" />}
              disabled={isSavingMeeting}
              onClick={handleEndMeeting}
            >
              {isSavingMeeting ? 'Saving...' : 'End Session'}
            </Button>
          </div>
        </div>

        {/* Right Side Drawer: Chat or AI Meeting Minutes */}
        <div className="w-80 md:w-96 glass-panel rounded-3xl flex flex-col overflow-hidden shrink-0">
          {/* Drawer Tabs */}
          <div className="flex border-b border-slate-800 bg-surface-900/60 p-2 gap-1">
            <button
              onClick={() => setActiveSideTab('chat')}
              className={`flex-1 py-2 text-xs font-semibold rounded-xl flex items-center justify-center gap-1.5 transition-colors ${
                activeSideTab === 'chat'
                  ? 'bg-brand-600/20 text-brand-400 border border-brand-500/30'
                  : 'text-slate-400 hover:text-slate-200'
              }`}
            >
              <MessageSquare className="w-3.5 h-3.5" />
              Room Chat ({messages.length})
            </button>

            <button
              onClick={() => setActiveSideTab('ai')}
              className={`flex-1 py-2 text-xs font-semibold rounded-xl flex items-center justify-center gap-1.5 transition-colors ${
                activeSideTab === 'ai'
                  ? 'bg-brand-600/20 text-brand-400 border border-brand-500/30'
                  : 'text-slate-400 hover:text-slate-200'
              }`}
            >
              <Sparkles className="w-3.5 h-3.5 text-cyan-400" />
              AI Summary
            </button>
          </div>

          {/* Chat Tab Panel */}
          {activeSideTab === 'chat' && (
            <div className="flex-1 flex flex-col min-h-0">
              <div className="flex-1 overflow-y-auto p-4 space-y-3">
                {messages.length === 0 ? (
                  <div className="py-12 text-center text-xs text-slate-500">
                    No messages yet. Send a greeting to the room!
                  </div>
                ) : (
                  messages.map((m) => (
                    <div
                      key={m.id}
                      className={`space-y-1 ${
                        m.isSystem
                          ? 'text-center my-2'
                          : m.sender === user.name
                          ? 'text-right'
                          : 'text-left'
                      }`}
                    >
                      {m.isSystem ? (
                        <span className="inline-block text-[11px] px-3 py-1 rounded-full bg-slate-800 text-slate-400">
                          {m.text}
                        </span>
                      ) : (
                        <div>
                          <div className="text-[10px] text-slate-500 font-medium">
                            {m.sender} • {m.timestamp}
                          </div>
                          <div
                            className={`inline-block px-3.5 py-2 rounded-2xl text-xs max-w-[85%] text-left ${
                              m.sender === user.name
                                ? 'bg-brand-600 text-white rounded-br-none'
                                : 'bg-slate-800 text-slate-200 rounded-bl-none'
                            }`}
                          >
                            {m.text}
                          </div>
                        </div>
                      )}
                    </div>
                  ))
                )}
                <div ref={chatEndRef} />
              </div>

              {/* Message Input Form */}
              <form
                onSubmit={handleSendMessage}
                className="p-3 border-t border-slate-800 flex items-center gap-2 bg-surface-900/60"
              >
                <input
                  type="text"
                  placeholder="Type a message to room..."
                  value={messageInput}
                  onChange={(e) => setMessageInput(e.target.value)}
                  className="flex-1 bg-slate-900 border border-slate-700 rounded-xl px-3.5 py-2 text-xs text-slate-100 placeholder-slate-500 focus:outline-none focus:border-brand-500"
                />
                <Button
                  type="submit"
                  variant="primary"
                  size="sm"
                  disabled={!messageInput.trim()}
                  icon={<Send className="w-3.5 h-3.5" />}
                >
                  Send
                </Button>
              </form>
            </div>
          )}

          {/* AI Summary Tab Panel */}
          {activeSideTab === 'ai' && (
            <div className="flex-1 overflow-y-auto p-4 space-y-5">
              <div className="flex items-center justify-between pb-2 border-b border-slate-800">
                <div className="text-xs font-bold text-slate-200 uppercase tracking-wider flex items-center gap-1.5">
                  <Sparkles className="w-3.5 h-3.5 text-cyan-400" />
                  Meeting Intelligence
                </div>
                <Badge variant="info">AI Powered</Badge>
              </div>

              {/* Executive Summary */}
              <div className="space-y-2">
                <div className="text-xs font-semibold text-slate-300 flex items-center gap-1.5">
                  <FileText className="w-3.5 h-3.5 text-brand-400" />
                  Executive Summary
                </div>
                <div className="p-3.5 rounded-2xl bg-slate-900/80 border border-slate-800 text-xs text-slate-300 leading-relaxed">
                  {aiSummary ||
                    'Click "Generate AI Minutes" at any time to summarize discussions, key decisions, and extracted tasks.'}
                </div>
              </div>

              {/* Key Decisions */}
              {keyDecisions.length > 0 && (
                <div className="space-y-2">
                  <div className="text-xs font-semibold text-slate-300 flex items-center gap-1.5">
                    <Shield className="w-3.5 h-3.5 text-emerald-400" />
                    Key Decisions ({keyDecisions.length})
                  </div>
                  <ul className="space-y-2">
                    {keyDecisions.map((decision, idx) => (
                      <li
                        key={idx}
                        className="p-2.5 rounded-xl bg-slate-900/60 border border-slate-800/80 text-xs text-slate-300 flex items-start gap-2"
                      >
                        <span className="text-emerald-400 font-bold">•</span>
                        <span>{decision}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}

              {/* Action Items Checklist */}
              {actionItems.length > 0 && (
                <div className="space-y-2">
                  <div className="text-xs font-semibold text-slate-300 flex items-center gap-1.5">
                    <ListTodo className="w-3.5 h-3.5 text-amber-400" />
                    Action Items ({actionItems.length})
                  </div>
                  <div className="space-y-2">
                    {actionItems.map((item) => (
                      <div
                        key={item.id}
                        onClick={() => toggleActionItem(item.id)}
                        className={`p-3 rounded-xl border text-xs cursor-pointer transition-all flex items-start gap-2.5 ${
                          item.completed
                            ? 'bg-emerald-950/20 border-emerald-800/40 text-slate-400 line-through'
                            : 'bg-slate-900/80 border-slate-800 text-slate-200 hover:border-slate-700'
                        }`}
                      >
                        <input
                          type="checkbox"
                          checked={item.completed}
                          onChange={() => {}}
                          className="mt-0.5 rounded border-slate-700 text-brand-600 focus:ring-0"
                        />
                        <div className="space-y-0.5">
                          <div>{item.text}</div>
                          <div className="text-[10px] text-slate-500">
                            Assignee: <span className="text-brand-400">{item.assignee}</span>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

import React, { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import { Building, Layers, Users, ArrowRight, Check, Video, Plus, Trash2 } from 'lucide-react'
import { Button } from '../../components/ui/Button'
import { Input } from '../../components/ui/Input'
import { Card } from '../../components/ui/Card'
import { useAuthStore } from '../../stores/authStore'
import { apiRequest } from '../../services/apiClient'

export const OnboardingPage: React.FC = () => {
  const navigate = useNavigate()
  const { setUserName } = useAuthStore()

  const [step, setStep] = useState<1 | 2 | 3>(1)
  const [orgName, setOrgName] = useState('Acme Corporation')
  const [teamSize, setTeamSize] = useState('11-50')
  const [workspaceName, setWorkspaceName] = useState('Engineering & Product')
  const [workspaceSlug, setWorkspaceSlug] = useState('eng-product')
  const [invites, setInvites] = useState([
    { email: 'alex@company.com', role: 'member' },
    { email: 'michael@company.com', role: 'member' },
  ])
  const [newEmail, setNewEmail] = useState('')

  const handleAddInvite = () => {
    if (newEmail && newEmail.includes('@')) {
      setInvites([...invites, { email: newEmail, role: 'member' }])
      setNewEmail('')
    }
  }

  const handleRemoveInvite = (idx: number) => {
    setInvites(invites.filter((_, i) => i !== idx))
  }

  const handleFinish = async () => {
    try {
      const slug = orgName.toLowerCase().replace(/[^a-z0-9]/g, '-') + '-' + Math.floor(Math.random() * 1000)
      await apiRequest('/organizations', {
        method: 'POST',
        body: JSON.stringify({
          name: orgName,
          slug,
          tier: 'enterprise',
        }),
      })
    } catch {
      // Continue to dashboard
    }
    navigate('/app')
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col justify-center py-12 px-4 sm:px-6 lg:px-8">
      {/* Brand & Stepper */}
      <div className="sm:mx-auto sm:w-full sm:max-w-xl text-center space-y-4">
        <div className="inline-flex items-center gap-2">
          <div className="w-10 h-10 rounded-xl bg-[#2563EB] flex items-center justify-center text-white shadow-subtle">
            <Video className="w-5 h-5" />
          </div>
          <span className="font-heading font-bold text-2xl tracking-tight text-[#101828]">
            Intell<span className="text-[#2563EB]">Meet</span>
          </span>
        </div>

        {/* Progress Pills */}
        <div className="flex items-center justify-center gap-2 pt-2">
          <div
            className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold ${
              step >= 1 ? 'bg-[#EFF8FF] text-[#175CD3] border border-[#B2DDFF]' : 'bg-[#EAECF0] text-[#98A2B3]'
            }`}
          >
            <span>1. Organization</span>
          </div>
          <span className="text-[#D0D5DD]">/</span>
          <div
            className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold ${
              step >= 2 ? 'bg-[#EFF8FF] text-[#175CD3] border border-[#B2DDFF]' : 'bg-[#EAECF0] text-[#98A2B3]'
            }`}
          >
            <span>2. Workspace</span>
          </div>
          <span className="text-[#D0D5DD]">/</span>
          <div
            className={`flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-semibold ${
              step === 3 ? 'bg-[#EFF8FF] text-[#175CD3] border border-[#B2DDFF]' : 'bg-[#EAECF0] text-[#98A2B3]'
            }`}
          >
            <span>3. Team</span>
          </div>
        </div>
      </div>

      <div className="mt-8 sm:mx-auto sm:w-full sm:max-w-xl">
        <Card className="space-y-6">
          {/* STEP 1: Organization Profile */}
          {step === 1 && (
            <div className="space-y-5 animate-fade-in">
              <div className="space-y-1">
                <h3 className="font-heading font-bold text-xl text-[#101828]">
                  Set up your organization profile
                </h3>
                <p className="text-xs text-[#667085]">
                  This establishes the parent domain and enterprise billing profile for your team.
                </p>
              </div>

              <div className="space-y-4">
                <Input
                  label="Organization Name"
                  value={orgName}
                  onChange={(e) => setOrgName(e.target.value)}
                  placeholder="Acme Global Inc."
                  icon={<Building className="w-4 h-4" />}
                  required
                />

                <div className="space-y-1.5 text-left">
                  <label className="block text-xs font-medium text-[#344054]">
                    Company Size
                  </label>
                  <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                    {['1-10', '11-50', '51-200', '201+'].map((size) => (
                      <button
                        key={size}
                        type="button"
                        onClick={() => setTeamSize(size)}
                        className={`p-2.5 rounded-lg border text-xs font-medium transition-all ${
                          teamSize === size
                            ? 'bg-[#EFF8FF] border-[#2563EB] text-[#175CD3] font-semibold'
                            : 'border-[#D0D5DD] text-[#344054] hover:bg-[#F8FAFC]'
                        }`}
                      >
                        {size} people
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              <div className="pt-3 border-t border-[#EAECF0] flex justify-end">
                <Button
                  variant="primary"
                  size="md"
                  iconRight={<ArrowRight className="w-4 h-4" />}
                  onClick={() => setStep(2)}
                >
                  Continue to Workspace
                </Button>
              </div>
            </div>
          )}

          {/* STEP 2: Workspace Setup */}
          {step === 2 && (
            <div className="space-y-5 animate-fade-in">
              <div className="space-y-1">
                <h3 className="font-heading font-bold text-xl text-[#101828]">
                  Create your first team workspace
                </h3>
                <p className="text-xs text-[#667085]">
                  Workspaces group meetings, transcripts, and AI insights by department or project.
                </p>
              </div>

              <div className="space-y-4">
                <Input
                  label="Workspace Name"
                  value={workspaceName}
                  onChange={(e) => {
                    setWorkspaceName(e.target.value)
                    setWorkspaceSlug(e.target.value.toLowerCase().replace(/\s+/g, '-'))
                  }}
                  placeholder="e.g. Core Engineering"
                  icon={<Layers className="w-4 h-4" />}
                  required
                />

                <div>
                  <label className="block text-xs font-medium text-[#344054] mb-1">
                    Workspace URL
                  </label>
                  <div className="flex items-center rounded-lg border border-[#D0D5DD] bg-[#F8FAFC] px-3 py-2 text-xs text-[#667085]">
                    <span>https://meet.intellmeet.com/ws/</span>
                    <span className="font-semibold text-[#101828] ml-0.5">{workspaceSlug || 'workspace'}</span>
                  </div>
                </div>
              </div>

              <div className="pt-3 border-t border-[#EAECF0] flex items-center justify-between">
                <Button variant="ghost" size="sm" onClick={() => setStep(1)}>
                  Back
                </Button>
                <Button
                  variant="primary"
                  size="md"
                  iconRight={<ArrowRight className="w-4 h-4" />}
                  onClick={() => setStep(3)}
                >
                  Continue to Team Invites
                </Button>
              </div>
            </div>
          )}

          {/* STEP 3: Invite Team Members */}
          {step === 3 && (
            <div className="space-y-5 animate-fade-in">
              <div className="space-y-1">
                <h3 className="font-heading font-bold text-xl text-[#101828]">
                  Invite your colleagues
                </h3>
                <p className="text-xs text-[#667085]">
                  Collaborate in real time with automated transcripts and shared meeting minutes.
                </p>
              </div>

              <div className="space-y-3">
                <div className="flex gap-2">
                  <Input
                    placeholder="colleague@company.com"
                    value={newEmail}
                    onChange={(e) => setNewEmail(e.target.value)}
                    icon={<Users className="w-4 h-4" />}
                  />
                  <Button
                    type="button"
                    variant="secondary"
                    size="md"
                    onClick={handleAddInvite}
                    icon={<Plus className="w-4 h-4" />}
                  >
                    Add
                  </Button>
                </div>

                <div className="space-y-2 max-h-48 overflow-y-auto">
                  {invites.map((inv, idx) => (
                    <div
                      key={idx}
                      className="flex items-center justify-between p-2.5 rounded-lg border border-[#EAECF0] bg-[#F8FAFC] text-xs"
                    >
                      <span className="font-medium text-[#101828]">{inv.email}</span>
                      <div className="flex items-center gap-2">
                        <span className="bg-white border border-[#D0D5DD] px-2 py-0.5 rounded text-[11px] text-[#667085]">
                          Member
                        </span>
                        <button
                          onClick={() => handleRemoveInvite(idx)}
                          className="text-[#98A2B3] hover:text-[#F04438]"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              <div className="pt-3 border-t border-[#EAECF0] flex items-center justify-between">
                <button
                  type="button"
                  onClick={handleFinish}
                  className="text-xs text-[#667085] hover:text-[#101828] font-medium"
                >
                  Skip for now
                </button>
                <Button
                  variant="primary"
                  size="md"
                  iconRight={<Check className="w-4 h-4" />}
                  onClick={handleFinish}
                >
                  Launch IntellMeet Dashboard
                </Button>
              </div>
            </div>
          )}
        </Card>
      </div>
    </div>
  )
}

import React, { useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { Video, Lock, Mail, User, Building, ArrowRight, Check } from 'lucide-react'
import { Button } from '../../components/ui/Button'
import { Input } from '../../components/ui/Input'
import { Card } from '../../components/ui/Card'
import { useAuthStore } from '../../stores/authStore'
import { authService } from '../../services/authService'

export const RegisterPage: React.FC = () => {
  const navigate = useNavigate()
  const { setUser } = useAuthStore()

  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [company, setCompany] = useState('')
  const [password, setPassword] = useState('')
  const [agreed, setAgreed] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  // Password rules validation
  const hasMinLength = password.length >= 8
  const hasNumber = /\d/.test(password)
  const hasSpecial = /[!@#$%^&*(),.?":{}|<>]/.test(password)
  const isPasswordValid = hasMinLength && hasNumber && hasSpecial

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!agreed) {
      setError('Please agree to the Terms of Service to continue.')
      return
    }
    if (!isPasswordValid) {
      setError('Please ensure password satisfies all security requirements.')
      return
    }

    setLoading(true)
    setError(null)

    try {
      const response = await authService.register({
        name,
        email,
        password,
        company,
        role: 'org_admin',
      })
      setUser({
        id: response.user.id,
        name: response.user.name,
        email: response.user.email,
        role: response.user.role,
        avatarUrl: response.user.avatarUrl || 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=120&h=120&q=80',
        status: 'active',
      })
      navigate('/app')
    } catch (err: any) {
      setError(err?.message || 'Registration failed. Please check information.')
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className="min-h-screen bg-[#F8FAFC] flex flex-col justify-center py-12 px-4 sm:px-6 lg:px-8">
      <div className="sm:mx-auto sm:w-full sm:max-w-md text-center space-y-2">
        <Link to="/" className="inline-flex items-center gap-2">
          <div className="w-10 h-10 rounded-xl bg-[#2563EB] flex items-center justify-center text-white shadow-subtle">
            <Video className="w-5 h-5" />
          </div>
          <span className="font-heading font-bold text-2xl tracking-tight text-[#101828]">
            Intell<span className="text-[#2563EB]">Meet</span>
          </span>
        </Link>
        <h2 className="font-heading text-2xl font-bold text-[#101828] tracking-tight">
          Create your enterprise account
        </h2>
        <p className="text-xs text-[#667085]">
          Start your 14-day full-featured enterprise trial. No credit card required.
        </p>
      </div>

      <div className="mt-8 sm:mx-auto sm:w-full sm:max-w-md">
        <Card className="space-y-5">
          {error && (
            <div className="p-3 bg-[#FEF3F2] border border-[#FECDCA] rounded-lg text-xs text-[#B42318]">
              {error}
            </div>
          )}

          <form onSubmit={handleRegister} className="space-y-4">
            <Input
              label="Full Name"
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Sarah Chen"
              icon={<User className="w-4 h-4" />}
              required
            />

            <Input
              label="Work Email Address"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="sarah@company.com"
              icon={<Mail className="w-4 h-4" />}
              required
            />

            <Input
              label="Company / Organization Name"
              type="text"
              value={company}
              onChange={(e) => setCompany(e.target.value)}
              placeholder="Acme Global Inc."
              icon={<Building className="w-4 h-4" />}
              required
            />

            <div>
              <Input
                label="Password"
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Create a strong password"
                icon={<Lock className="w-4 h-4" />}
                required
              />

              {/* Password strength checklist */}
              <div className="mt-2.5 p-3 rounded-lg bg-[#F8FAFC] border border-[#EAECF0] space-y-1.5 text-xs text-[#667085]">
                <div className="text-[11px] font-semibold text-[#344054]">Security Requirements:</div>
