        <div className="flex items-center gap-1 bg-[#F8FAFC] border border-[#EAECF0] p-1 rounded-lg text-xs">
          <button
            onClick={() => setViewMode('day')}
            className={`px-3 py-1 rounded-md font-medium transition-all ${
              viewMode === 'day'
                ? 'bg-white text-[#101828] shadow-xs font-semibold'
                : 'text-[#667085] hover:text-[#101828]'
            }`}
          >
            Day View
          </button>
          <button
            onClick={() => setViewMode('week')}
            className={`px-3 py-1 rounded-md font-medium transition-all ${
              viewMode === 'week'
                ? 'bg-white text-[#101828] shadow-xs font-semibold'
                : 'text-[#667085] hover:text-[#101828]'
            }`}
          >
            Week View
          </button>
          <button
            onClick={() => setViewMode('month')}
            className={`px-3 py-1 rounded-md font-medium transition-all ${
              viewMode === 'month'
                ? 'bg-white text-[#101828] shadow-xs font-semibold'
                : 'text-[#667085] hover:text-[#101828]'
            }`}
          >
            Month View
          </button>
        </div>
      </div>

      {/* VIEW 1: MONTH VIEW */}
      {viewMode === 'month' && (
        <Card padding="none" className="overflow-hidden">
          {/* Weekday headers */}
          <div className="grid grid-cols-7 border-b border-[#EAECF0] bg-[#F8FAFC] text-center text-[11px] font-semibold text-[#667085] py-2.5">
            <div>SUN</div>
            <div>MON</div>
            <div>TUE</div>
            <div>WED</div>
            <div>THU</div>
            <div>FRI</div>
            <div>SAT</div>
          </div>

          {/* Month day grid */}
          <div className="grid grid-cols-7 auto-rows-fr divide-x divide-y divide-[#EAECF0] bg-white">
            {/* Empty offset padding for days before 1st */}
            {Array.from({ length: firstDayOfWeek }).map((_, idx) => (
              <div key={`empty_${idx}`} className="h-28 bg-[#F8FAFC]/50 p-2" />
            ))}

            {/* Days in Month */}
            {Array.from({ length: daysInMonth }).map((_, idx) => {
              const dayNumber = idx + 1
              const dayMeetings = meetings.filter((m) => {
                const d = new Date(m.scheduledStartTime || m.createdAt)
                return d.getDate() === dayNumber && d.getMonth() === currentMonth
              })

              const isToday = dayNumber === 2 && currentMonth === 10

              return (
                <div
                  key={`day_${dayNumber}`}
                  className={`h-28 p-2 overflow-y-auto space-y-1 transition-colors hover:bg-[#F8FAFC] ${
                    isToday ? 'bg-[#EFF8FF]/40' : ''
                  }`}
                >
                  <div className="flex items-center justify-between">
                    <span
                      className={`text-xs font-bold ${
                        isToday
                          ? 'w-5 h-5 rounded-full bg-[#2563EB] text-white flex items-center justify-center'
                          : 'text-[#475467]'
                      }`}
                    >
                      {dayNumber}
                    </span>
                  </div>

                  {dayMeetings.map((m, mIdx) => (
                    <div
                      key={m.roomId || mIdx}
                      onClick={() => openMeetingDetails(m)}
                      className="p-1 rounded bg-[#EFF8FF] text-[#175CD3] border border-[#B2DDFF] text-[10px] font-medium truncate cursor-pointer hover:bg-[#D1E9FF] transition-colors"
                      title={m.title}
                    >
                      {m.title}
                    </div>
                  ))}
                </div>
              )
            })}
          </div>
        </Card>
      )}

      {/* VIEW 2: WEEK VIEW */}
      {viewMode === 'week' && (
        <Card padding="none" className="overflow-hidden">
          <div className="grid grid-cols-7 border-b border-[#EAECF0] bg-[#F8FAFC] text-center text-xs font-semibold text-[#667085] py-3">
            <div>Mon, Nov 2</div>
            <div>Tue, Nov 3</div>
            <div>Wed, Nov 4</div>
            <div>Thu, Nov 5</div>
            <div>Fri, Nov 6</div>
            <div>Sat, Nov 7</div>
            <div>Sun, Nov 8</div>
          </div>
          <div className="grid grid-cols-7 divide-x divide-[#EAECF0] min-h-[360px] bg-white p-2">
            {Array.from({ length: 7 }).map((_, idx) => {
              const dayNumber = idx + 2
              const dayMeetings = meetings.filter((m) => {
                const d = new Date(m.scheduledStartTime || m.createdAt)
                return d.getDate() === dayNumber
              })

              return (
                <div key={idx} className="p-2 space-y-2">
                  {dayMeetings.map((m, mIdx) => (
                    <div
                      key={m.roomId || mIdx}
                      onClick={() => openMeetingDetails(m)}
                      className="p-2.5 rounded-xl bg-[#EFF8FF] border border-[#B2DDFF] text-xs space-y-1 cursor-pointer hover:shadow-subtle transition-all"
                    >
                      <div className="font-semibold text-[#175CD3] line-clamp-1">{m.title}</div>
                      <div className="text-[10px] text-[#2563EB] flex items-center gap-1">
                        <Clock className="w-3 h-3" /> {m.durationMinutes || 45} mins
                      </div>
                    </div>
                  ))}
                </div>
              )
            })}
          </div>
        </Card>
      )}

      {/* VIEW 3: DAY VIEW */}
      {viewMode === 'day' && (
        <Card className="space-y-4">
          <div className="flex items-center justify-between border-b border-[#EAECF0] pb-3">
            <h3 className="font-heading font-semibold text-sm text-[#101828]">
              Agenda for Today: Monday, Nov 2, 2026
            </h3>
            <Badge variant="primary" size="sm">
              3 Scheduled Sessions
            </Badge>
          </div>

          <div className="space-y-3">
            {meetings.map((m, idx) => (
              <div
                key={m.roomId || idx}
                onClick={() => openMeetingDetails(m)}
                className="p-4 rounded-xl border border-[#EAECF0] bg-[#F8FAFC] hover:bg-white hover:border-[#2563EB] hover:shadow-subtle transition-all cursor-pointer flex flex-col sm:flex-row sm:items-center justify-between gap-3"
              >
                <div className="space-y-1">
                  <div className="flex items-center gap-2">
                    <span className="font-semibold text-sm text-[#101828]">{m.title}</span>
                    <Badge variant="primary" size="sm">
                      {m.roomId}
                    </Badge>
                  </div>
                  <div className="flex flex-wrap items-center gap-3 text-xs text-[#667085]">
                    <span className="flex items-center gap-1">
                      <Clock className="w-3.5 h-3.5 text-[#98A2B3]" /> 14:00 – 14:45 ({m.timezone || 'UTC-5'})
                    </span>
                    <span>•</span>
                    <span className="flex items-center gap-1">
                      <Users className="w-3.5 h-3.5 text-[#98A2B3]" /> Host: {m.hostName || 'Sarah Chen'}
                    </span>
                  </div>
                </div>

                <div className="flex items-center gap-2">
                  <Link to={`/room/${m.roomId}`}>
                    <Button variant="primary" size="sm" icon={<Video className="w-3.5 h-3.5" />}>
                      Join Meeting
                    </Button>
                  </Link>
                </div>
              </div>
            ))}
          </div>
        </Card>
      )}

      {/* External Calendar Provider Sync Integration Card */}
      <Card className="p-5 border border-[#EAECF0] bg-white space-y-4">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-[#EAECF0] pb-3">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-xl bg-[#EFF8FF] text-[#2563EB] flex items-center justify-center shrink-0">
              <Globe className="w-5 h-5" />
            </div>
            <div>
              <h3 className="font-heading font-semibold text-sm text-[#101828]">
                External Calendar Provider Sync
              </h3>
              <p className="text-xs text-[#667085]">
                Bi-directional calendar synchronisation with Google Workspace & Microsoft 365.
              </p>
            </div>
          </div>

          <Badge variant="gray" size="sm">
            Ready for OAuth Link
          </Badge>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs">
          <div className="p-3.5 rounded-xl border border-[#EAECF0] bg-[#F8FAFC] flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 rounded-lg bg-white border border-[#D0D5DD] flex items-center justify-center font-bold text-[#EA4335]">
                G
              </div>
              <div>
                <div className="font-semibold text-[#101828]">Google Calendar</div>
                <div className="text-[11px] text-[#667085]">Status: Not connected</div>
              </div>
            </div>
            <Button variant="outline" size="sm">
              Connect Google
            </Button>
          </div>

          <div className="p-3.5 rounded-xl border border-[#EAECF0] bg-[#F8FAFC] flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 rounded-lg bg-white border border-[#D0D5DD] flex items-center justify-center font-bold text-[#0078D4]">
                M
              </div>
              <div>
                <div className="font-semibold text-[#101828]">Microsoft Outlook</div>
                <div className="text-[11px] text-[#667085]">Status: Not connected</div>
              </div>
            </div>
            <Button variant="outline" size="sm">
              Connect Outlook
            </Button>
          </div>
        </div>
      </Card>

      {/* Meeting Details Modal */}
      {selectedMeeting && (
        <Modal
          isOpen={detailsModalOpen}
          onClose={() => setDetailsModalOpen(false)}
          title="Meeting Details"
          description="Review scheduled parameters and attendee roster."
        >
          <div className="space-y-4 pt-2 text-xs">
            <div className="p-3 rounded-xl bg-[#F8FAFC] border border-[#EAECF0] space-y-2">
              <div className="flex justify-between">
                <span className="text-[#667085]">Title:</span>
                <span className="font-semibold text-[#101828]">{selectedMeeting.title}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-[#667085]">Room Code:</span>
                <span className="font-mono text-[#2563EB] font-bold">{selectedMeeting.roomId}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-[#667085]">Host:</span>
                <span className="text-[#101828] font-medium">{selectedMeeting.hostName || 'Host'}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-[#667085]">Duration:</span>
                <span className="text-[#101828]">{selectedMeeting.durationMinutes || 45} minutes</span>
              </div>
              <div className="flex justify-between">
                <span className="text-[#667085]">Timezone:</span>
                <span className="text-[#101828]">{selectedMeeting.timezone || 'UTC'}</span>
              </div>
            </div>

            <div className="flex justify-end gap-2 pt-2">
              <Button
                variant="secondary"
                size="sm"
                onClick={() => setDetailsModalOpen(false)}
              >
                Close
              </Button>
              <Button
                variant="primary"
                size="sm"
                onClick={() => {
                  setDetailsModalOpen(false)
                  navigate(`/room/${selectedMeeting.roomId}`)
                }}
                icon={<Video className="w-3.5 h-3.5" />}
              >
                Join Meeting
              </Button>
            </div>
          </div>
        </Modal>
      )}
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import { Link } from 'react-router-dom'
import {
  CheckSquare,
  Plus,
  Filter,
  CheckCircle2,
  Clock,
  User,
  AlertCircle,
  MoreVertical,
  Calendar,
  Sparkles,
  Edit2,
  RefreshCw,
  Loader2,
  Quote,
} from 'lucide-react'
import { Button } from '../../components/ui/Button'
import { Badge } from '../../components/ui/Badge'
import { Card } from '../../components/ui/Card'
import { Modal } from '../../components/ui/Modal'
import { Input } from '../../components/ui/Input'
import { actionItemService, ActionItemDto } from '../../services/actionItemService'
import { aiService } from '../../services/aiService'
import { useToast } from '../../contexts/ToastContext'

export const TasksPage: React.FC = () => {
  const { success, info, error } = useToast()
  const [filterStatus, setFilterStatus] = useState<'all' | 'pending' | 'completed'>('all')
  const [tasks, setTasks] = useState<ActionItemDto[]>([])
  const [isLoading, setIsLoading] = useState(true)
  const [isExtracting, setIsExtracting] = useState(false)

  // Create Modal
  const [createModalOpen, setCreateModalOpen] = useState(false)
  const [newTaskTitle, setNewTaskTitle] = useState('')
  const [newTaskAssignee, setNewTaskAssignee] = useState('Unassigned')
  const [newTaskPriority, setNewTaskPriority] = useState<'low' | 'medium' | 'high'>('medium')
  const [newTaskDue, setNewTaskDue] = useState('')

  // Edit Modal
  const [editModalOpen, setEditModalOpen] = useState(false)
  const [editingTask, setEditingTask] = useState<ActionItemDto | null>(null)
  const [editTitle, setEditTitle] = useState('')
  const [editAssignee, setEditAssignee] = useState('')
  const [editPriority, setEditPriority] = useState<'low' | 'medium' | 'high'>('medium')
  const [editDue, setEditDue] = useState('')
  const [editStatus, setEditStatus] = useState<'pending' | 'in_progress' | 'completed' | 'cancelled'>('pending')

  const fetchTasks = async () => {
    setIsLoading(true)
    try {
      const items = await actionItemService.getActionItems()
      setTasks(items)
    } catch {
      // Fallback sample tasks
      setTasks([
        {
          _id: 'task_1',
          id: 'task_1',
          title: 'Finalize WebRTC STUN/TURN fallback verification',
          assigneeName: 'Engineering Team',
          dueDate: '2026-11-01',
          priority: 'high',
          status: 'completed',
          relatedDiscussion: 'Sarah Chen: Finalize the WebRTC pipeline while QA verifies broadcasting.',
        },
        {
          _id: 'task_2',
          id: 'task_2',
          title: 'Review SOC-2 audit logging requirements for transcript storage',
          assigneeName: 'David Miller',
          dueDate: '2026-11-02',
          priority: 'medium',
          status: 'pending',
          relatedDiscussion: 'Sarah Chen: Let us verify the 12 Mongoose models and build the full enterprise design system.',
        },
        {
          _id: 'task_3',
          id: 'task_3',
          title: 'Deploy Phase 2 modern enterprise frontend design system',
          assigneeName: 'Frontend Architect',
          dueDate: '2026-11-03',
          priority: 'high',
          status: 'pending',
          relatedDiscussion: 'Elena Rostova: The on-device Web Speech API generates subtitles directly on the user client.',
        },
      ])
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
    fetchTasks()
  }, [])

  const toggleTask = async (task: ActionItemDto) => {
    const newStatus = task.status === 'completed' ? 'pending' : 'completed'
    const taskId = task._id || task.id || ''

    // Optimistic update
    setTasks((prev) =>
      prev.map((t) =>
        (t._id === taskId || t.id === taskId) ? { ...t, status: newStatus } : t
      )
    )

    try {
      await actionItemService.updateActionItem(taskId, { status: newStatus })
      info(`Task marked as ${newStatus}`)
    } catch {
      // Revert if error
      fetchTasks()
    }
  }

  const handleCreateTask = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!newTaskTitle.trim()) return

    const payload = {
      title: newTaskTitle.trim(),
      text: newTaskTitle.trim(),
      assigneeName: newTaskAssignee.trim() || 'Unassigned',
      priority: newTaskPriority,
      dueDate: newTaskDue || undefined,
      status: 'pending' as const,
    }

    try {
      const created = await actionItemService.createActionItem(payload)
      setTasks((prev) => [created, ...prev])
      success('Action item created successfully')
    } catch {
      setTasks((prev) => [
        {
          _id: `task_${Date.now()}`,
          id: `task_${Date.now()}`,
          ...payload,
        },
        ...prev,
      ])
      success('Action item created')
    }

    setNewTaskTitle('')
    setNewTaskAssignee('Unassigned')
    setNewTaskDue('')
    setCreateModalOpen(false)
  }

  const openEditModal = (task: ActionItemDto, e: React.MouseEvent) => {
    e.stopPropagation()
    setEditingTask(task)
    setEditTitle(task.title || task.text || '')
    setEditAssignee(task.assigneeName || task.assignee || 'Unassigned')
    setEditPriority(task.priority)
    setEditDue(task.dueDate ? String(task.dueDate).slice(0, 10) : '')
    setEditStatus(task.status)
    setEditModalOpen(true)
  }

  const handleSaveEdit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!editingTask) return

    const taskId = editingTask._id || editingTask.id || ''
    const updates = {
      title: editTitle.trim(),
      text: editTitle.trim(),
      assigneeName: editAssignee.trim() || 'Unassigned',
      priority: editPriority,
      dueDate: editDue || undefined,
      status: editStatus,
    }

    // Optimistic update
    setTasks((prev) =>
      prev.map((t) => (t._id === taskId || t.id === taskId ? { ...t, ...updates } : t))
    )
    setEditModalOpen(false)

    try {
      await actionItemService.updateActionItem(taskId, updates)
      success('Task details updated')
    } catch {
      fetchTasks()
    }
  }

  const handleExtractFromAi = async () => {
    setIsExtracting(true)
    try {
      const extracted = await aiService.extractTasks('room_default_demo', [
        { speaker: 'Sarah Chen', text: 'David will finalize the WebRTC pipeline while QA verifies multi-user broadcasting.' },
        { speaker: 'David Miller', text: 'I will submit the pull request tomorrow after STUN testing.' },
      ])

      if (extracted && extracted.length > 0) {
        // Save extracted items to backend
        for (const item of extracted) {
          try {
            await actionItemService.createActionItem({
              title: item.title,
              text: item.title,
              assigneeName: item.assignee || 'Unassigned',
              priority: item.priority || 'medium',
              dueDate: item.dueDate || undefined,
              status: 'pending',
              relatedDiscussion: item.relatedDiscussion,
            })
          } catch {}
        }
        await fetchTasks()
        success(`Extracted ${extracted.length} action items from meeting transcript`)
      }
    } catch (err) {
      console.error('Failed to extract tasks:', err)
      error('Failed to extract tasks from AI model')
    } finally {
      setIsExtracting(false)
    }
  }

  const filteredTasks = tasks.filter((t) => {
    const isComp = t.status === 'completed'
    if (filterStatus === 'pending') return !isComp
    if (filterStatus === 'completed') return isComp
    return true
  })

  return (
    <div className="max-w-6xl mx-auto space-y-6 animate-fade-in pb-12">
      {/* Page Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-4 border-b border-[#EAECF0]">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="font-heading text-2xl font-bold text-[#101828]">
              Tasks & Action Items
            </h1>
            <Badge variant="primary" size="sm">
              {tasks.filter((t) => t.status !== 'completed').length} Pending
            </Badge>
          </div>
          <p className="text-xs text-[#667085] mt-0.5">
            Strictly grounded action items extracted autonomously from team meetings. Review, assign, and edit tasks.
          </p>
        </div>

        <div className="flex items-center gap-2">
          <Button
            variant="secondary"
            size="sm"
            onClick={handleExtractFromAi}
            disabled={isExtracting}
            icon={
              isExtracting ? (
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
              ) : (
                <Sparkles className="w-3.5 h-3.5 text-[#2563EB]" />
              )
            }
          >
            {isExtracting ? 'Extracting...' : 'Extract with AI'}
          </Button>

          <Button
            variant="primary"
            size="sm"
            icon={<Plus className="w-4 h-4" />}
            onClick={() => setCreateModalOpen(true)}
          >
            Add Action Item
          </Button>
        </div>
      </div>

      {/* Filter Tabs */}
      <div className="flex items-center gap-2 text-xs">
        <button
          onClick={() => setFilterStatus('all')}
          className={`px-3 py-1.5 rounded-lg font-medium transition-colors ${
            filterStatus === 'all'
              ? 'bg-[#101828] text-white'
              : 'bg-white border border-[#D0D5DD] text-[#344054] hover:bg-[#F8FAFC]'
          }`}
        >
          All Tasks ({tasks.length})
        </button>
        <button
          onClick={() => setFilterStatus('pending')}
          className={`px-3 py-1.5 rounded-lg font-medium transition-colors ${
            filterStatus === 'pending'
              ? 'bg-[#101828] text-white'
              : 'bg-white border border-[#D0D5DD] text-[#344054] hover:bg-[#F8FAFC]'
          }`}
        >
          Pending ({tasks.filter((t) => t.status !== 'completed').length})
        </button>
        <button
          onClick={() => setFilterStatus('completed')}
          className={`px-3 py-1.5 rounded-lg font-medium transition-colors ${
            filterStatus === 'completed'
              ? 'bg-[#101828] text-white'
              : 'bg-white border border-[#D0D5DD] text-[#344054] hover:bg-[#F8FAFC]'
          }`}
        >
          Completed ({tasks.filter((t) => t.status === 'completed').length})
        </button>
      </div>

      {/* Tasks List */}
      <div className="space-y-3">
        {isLoading ? (
          <div className="py-12 text-center text-xs text-[#667085] flex items-center justify-center gap-2">
            <Loader2 className="w-4 h-4 animate-spin text-[#2563EB]" /> Loading action items...
          </div>
        ) : filteredTasks.length === 0 ? (
          <div className="py-12 text-center text-xs text-[#667085]">
            No action items found for this view.
          </div>
        ) : (
          filteredTasks.map((task) => {
            const isDone = task.status === 'completed'
            return (
              <Card
                key={task._id || task.id}
                hoverable
                className={`p-4 flex flex-col sm:flex-row sm:items-center justify-between gap-4 transition-all cursor-pointer ${
                  isDone ? 'bg-[#F8FAFC] opacity-75' : 'bg-white'
                }`}
                onClick={() => toggleTask(task)}
              >
                <div className="flex items-start gap-3.5 flex-1">
                  <input
                    type="checkbox"
                    checked={isDone}
                    onChange={() => {}}
                    className="mt-0.5 rounded border-[#D0D5DD] text-[#2563EB] focus:ring-0 w-4 h-4 cursor-pointer"
                  />
                  <div className="space-y-1.5">
                    <span
                      className={`text-sm font-medium ${
                        isDone ? 'line-through text-[#98A2B3]' : 'text-[#101828]'
                      }`}
                    >
                      {task.title || task.text}
                    </span>

                    <div className="flex flex-wrap items-center gap-3 text-xs text-[#667085]">
                      <span className="flex items-center gap-1">
                        <User className="w-3.5 h-3.5 text-[#98A2B3]" /> Assignee:{' '}
                        <span className="text-[#2563EB] font-medium">
                          {task.assigneeName || task.assignee || 'Unassigned'}
                        </span>
                      </span>

                      {task.dueDate && (
                        <>
                          <span>•</span>
                          <span className="flex items-center gap-1">
                            <Calendar className="w-3.5 h-3.5 text-[#98A2B3]" /> Due:{' '}
                            {String(task.dueDate).slice(0, 10)}
                          </span>
                        </>
                      )}
                    </div>

                    {task.relatedDiscussion && (
                      <div className="text-[11px] text-[#475467] bg-[#F8FAFC] px-2.5 py-1 rounded border border-[#EAECF0] flex items-center gap-1.5">
                        <Quote className="w-3 h-3 text-[#2563EB] shrink-0" />
                        <span className="truncate">{task.relatedDiscussion}</span>
                      </div>
                    )}

                    {task.meetingId && (
                      <div className="pt-0.5">
                        <Link
                          to={`/app/insights?meetingId=${task.meetingId}`}
                          onClick={(e) => e.stopPropagation()}
                          className="inline-flex items-center gap-1 text-[10px] font-semibold text-[#2563EB] bg-[#EFF8FF] px-2 py-0.5 rounded border border-[#B2DDFF] hover:bg-[#D1E9FF] transition-colors"
                        >
                          <Sparkles className="w-3 h-3 text-[#2563EB]" />
                          Linked: {task.meetingTitle || `Meeting ${task.meetingId}`}
                        </Link>
                      </div>
                    )}
                  </div>
                </div>

                <div className="shrink-0 flex items-center gap-2 self-end sm:self-center">
                  <Badge
                    variant={
                      task.priority === 'high'
                        ? 'error'
                        : task.priority === 'medium'
                        ? 'warning'
                        : 'gray'
                    }
                    size="sm"
                  >
                    {task.priority.toUpperCase()}
                  </Badge>

                  <button
                    onClick={(e) => openEditModal(task, e)}
                    className="p-1.5 rounded-lg text-[#667085] hover:text-[#101828] hover:bg-[#F2F4F7] transition-colors"
                    title="Edit task details"
                  >
                    <Edit2 className="w-3.5 h-3.5" />
                  </button>
                </div>
              </Card>
            )
          })
        )}
      </div>

      {/* Add Task Modal */}
      <Modal
        isOpen={createModalOpen}
        onClose={() => setCreateModalOpen(false)}
        title="Add Action Item"
        description="Create a discrete to-do task associated with your workspace."
      >
        <form onSubmit={handleCreateTask} className="space-y-4 pt-2">
          <Input
            label="Task Title / Description"
            placeholder="e.g. Verify STUN candidate exchange"
            value={newTaskTitle}
            onChange={(e) => setNewTaskTitle(e.target.value)}
            required
            autoFocus
          />

          <div className="grid grid-cols-2 gap-3">
            <Input
              label="Assignee Name"
              value={newTaskAssignee}
              onChange={(e) => setNewTaskAssignee(e.target.value)}
              placeholder="e.g. Sarah Chen or Unassigned"
              required
            />

            <div className="space-y-1.5 text-left">
              <label className="block text-xs font-medium text-[#344054]">Priority</label>
              <select
                value={newTaskPriority}
                onChange={(e) => setNewTaskPriority(e.target.value as any)}
                className="w-full rounded-lg border border-[#D0D5DD] bg-white px-3 py-2 text-xs text-[#101828] focus:border-[#2563EB] focus:outline-none"
              >
                <option value="low">Low Priority</option>
                <option value="medium">Medium Priority</option>
                <option value="high">High Priority</option>
              </select>
            </div>
          </div>

          <Input
            label="Due Date (optional)"
            type="date"
            value={newTaskDue}
            onChange={(e) => setNewTaskDue(e.target.value)}
          />

          <div className="flex justify-end gap-2 pt-2">
            <Button
              type="button"
              variant="secondary"
              size="sm"
              onClick={() => setCreateModalOpen(false)}
            >
              Cancel
            </Button>
            <Button type="submit" variant="primary" size="sm">
              Save Action Item
            </Button>
          </div>
        </form>
      </Modal>

      {/* Edit Task Modal */}
      <Modal
        isOpen={editModalOpen}
        onClose={() => setEditModalOpen(false)}
        title="Review & Edit Action Item"
        description="Verify or adjust extracted task assignment, priority, and due dates."
      >
        <form onSubmit={handleSaveEdit} className="space-y-4 pt-2">
          <Input
            label="Task Title"
            value={editTitle}
            onChange={(e) => setEditTitle(e.target.value)}
            required
            autoFocus
          />

          <div className="grid grid-cols-2 gap-3">
            <Input
              label="Assignee"
              value={editAssignee}
              onChange={(e) => setEditAssignee(e.target.value)}
              required
            />

            <div className="space-y-1.5 text-left">
              <label className="block text-xs font-medium text-[#344054]">Priority</label>
              <select
                value={editPriority}
                onChange={(e) => setEditPriority(e.target.value as any)}
                className="w-full rounded-lg border border-[#D0D5DD] bg-white px-3 py-2 text-xs text-[#101828] focus:border-[#2563EB] focus:outline-none"
              >
                <option value="low">Low Priority</option>
                <option value="medium">Medium Priority</option>
                <option value="high">High Priority</option>
              </select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <Input
              label="Due Date"
              type="date"
              value={editDue}
              onChange={(e) => setEditDue(e.target.value)}
            />

            <div className="space-y-1.5 text-left">
              <label className="block text-xs font-medium text-[#344054]">Status</label>
              <select
                value={editStatus}
                onChange={(e) => setEditStatus(e.target.value as any)}
                className="w-full rounded-lg border border-[#D0D5DD] bg-white px-3 py-2 text-xs text-[#101828] focus:border-[#2563EB] focus:outline-none"
              >
                <option value="pending">Pending</option>
                <option value="in_progress">In Progress</option>
                <option value="completed">Completed</option>
                <option value="cancelled">Cancelled</option>
              </select>
            </div>
          </div>

          <div className="flex justify-end gap-2 pt-2">
            <Button
              type="button"
              variant="secondary"
              size="sm"
              onClick={() => setEditModalOpen(false)}
            >
              Cancel
            </Button>
            <Button type="submit" variant="primary" size="sm">
              Save Changes
            </Button>
          </div>
        </form>
      </Modal>
    </div>
  )
}

import React, { useState, useEffect } from 'react'
import {
  Layers,
  Users,
  UserPlus,
  Shield,
  Search,
  MoreVertical,
  Mail,
  CheckCircle2,
  Trash2,
  Settings,
  Activity,
  HardDrive,
  Video,
  ListTodo,
  Lock,
  Globe,
  Loader2,
  Building2,
  Save,
} from 'lucide-react'
import { Button } from '../../components/ui/Button'
import { Badge } from '../../components/ui/Badge'
import { Card } from '../../components/ui/Card'
import { Modal } from '../../components/ui/Modal'
import { Input } from '../../components/ui/Input'
import { Tabs } from '../../components/ui/Tabs'
import { useAuthStore } from '../../stores/authStore'
import {
  workspaceService,
  WorkspaceMemberDto,
  WorkspaceDashboardStats,
  WorkspaceActivityItem,
} from '../../services/workspaceService'
import { useToast } from '../../contexts/ToastContext'

export const WorkspacePage: React.FC = () => {
  const { workspaceName, setWorkspaceName } = useAuthStore()
  const { success, info, error } = useToast()

  const [activeTab, setActiveTab] = useState<'members' | 'activity' | 'settings'>('members')
  const [searchQuery, setSearchQuery] = useState('')
  const [isLoading, setIsLoading] = useState(true)

  // Data states
  const [stats, setStats] = useState<WorkspaceDashboardStats | null>(null)
  const [members, setMembers] = useState<WorkspaceMemberDto[]>([])
  const [activities, setActivities] = useState<WorkspaceActivityItem[]>([])

  // Modal states
  const [inviteModalOpen, setInviteModalOpen] = useState(false)
  const [inviteEmail, setInviteEmail] = useState('')
  const [inviteRole, setInviteRole] = useState<'owner' | 'admin' | 'member' | 'guest'>('member')
  const [isInviting, setIsInviting] = useState(false)

  // Role Change Modal
  const [roleModalOpen, setRoleModalOpen] = useState(false)
  const [selectedMember, setSelectedMember] = useState<WorkspaceMemberDto | null>(null)
  const [targetRole, setTargetRole] = useState<'owner' | 'admin' | 'member' | 'guest'>('member')

  // Settings states
  const [wsName, setWsName] = useState(workspaceName || 'Core Engineering')
  const [wsSlug, setWsSlug] = useState('core-eng')
  const [wsDescription, setWsDescription] = useState('Central infrastructure, WebRTC streaming, and collaboration engineering.')
  const [wsIsPrivate, setWsIsPrivate] = useState(false)
  const [isSavingSettings, setIsSavingSettings] = useState(false)
  const [settingsSaved, setSettingsSaved] = useState(false)

  const fetchData = async () => {
    setIsLoading(true)
    try {
      const [statsData, membersData, activityData] = await Promise.all([
        workspaceService.getDashboard().catch(() => null),
        workspaceService.getMembers().catch(() => []),
        workspaceService.getActivity().catch(() => []),
      ])

      if (statsData) setStats(statsData)
      if (membersData) setMembers(membersData)
      if (activityData) setActivities(activityData)
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
    fetchData()
  }, [])

  const handleSendInvite = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!inviteEmail.trim() || isInviting) return

    setIsInviting(true)
    try {
      await workspaceService.inviteMember('ws_general', inviteEmail.trim(), inviteRole)
      success(`Invitation sent to ${inviteEmail.trim()}`)
      setInviteEmail('')
      setInviteModalOpen(false)
      await fetchData()
    } catch (err) {
      console.error('Failed to invite member:', err)
      error('Failed to send workspace invitation')
    } finally {
      setIsInviting(false)
    }
  }

  const handleOpenRoleModal = (member: WorkspaceMemberDto) => {
    setSelectedMember(member)
    setTargetRole(member.role)
    setRoleModalOpen(true)
  }

  const handleSaveRole = async () => {
    if (!selectedMember) return
    const memberId = selectedMember._id || selectedMember.id || ''

    try {
      await workspaceService.updateMemberRole('ws_general', memberId, targetRole)
      success(`Role updated to ${targetRole}`)
      setRoleModalOpen(false)
      await fetchData()
    } catch (err) {
      console.error('Failed to update role:', err)
      error('Failed to update member role')
    }
  }

  const handleRemoveMember = async (memberId: string) => {
    if (!confirm('Are you sure you want to remove this member from the workspace?')) return
    try {
      await workspaceService.removeMember('ws_general', memberId)
      info('Member removed from workspace')
      await fetchData()
    } catch (err) {
      console.error('Failed to remove member:', err)
      error('Failed to remove member')
    }
  }

  const handleSaveSettings = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsSavingSettings(true)
    try {
      await workspaceService.updateSettings('ws_general', {
        name: wsName,
        slug: wsSlug,
        description: wsDescription,
        isPrivate: wsIsPrivate,
      })
      setWorkspaceName(wsName)
      setSettingsSaved(true)
      success('Workspace settings updated successfully')
      setTimeout(() => setSettingsSaved(false), 2000)
    } catch (err) {
      console.error('Failed to save settings:', err)
      error('Failed to update workspace settings')
    } finally {
      setIsSavingSettings(false)
    }
  }

  const filteredMembers = members.filter((m) => {
    const name = m.userId?.name || ''
    const email = m.userId?.email || ''
    return (
      name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      email.toLowerCase().includes(searchQuery.toLowerCase())
    )
  })

  return (
    <div className="max-w-6xl mx-auto space-y-6 animate-fade-in pb-12">
      {/* Page Title & Actions */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-4 border-b border-[#EAECF0]">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="font-heading text-2xl font-bold text-[#101828]">
              {wsName}
            </h1>
            <Badge variant="primary" size="sm">
              <Building2 className="w-3.5 h-3.5 text-[#2563EB]" /> Enterprise Workspace
            </Badge>
          </div>
          <p className="text-xs text-[#667085] mt-0.5">
            Manage team members, roles, permissions, audit activity, and collaboration settings.
          </p>
        </div>

        <Button
          variant="primary"
          size="sm"
          icon={<UserPlus className="w-4 h-4" />}
          onClick={() => setInviteModalOpen(true)}
        >
          Invite Member
        </Button>
      </div>

      {/* Workspace Dashboard Stats Grid */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3.5">
        <Card className="p-3.5 flex items-center gap-3">
          <div className="w-9 h-9 rounded-lg bg-[#EFF8FF] text-[#2563EB] flex items-center justify-center shrink-0">
            <Users className="w-4 h-4" />
          </div>
          <div>
            <div className="text-[11px] font-medium text-[#667085]">Team Members</div>
            <div className="text-base font-bold text-[#101828]">
              {members.length || stats?.memberCount || 4}
            </div>
          </div>
        </Card>

        <Card className="p-3.5 flex items-center gap-3">
          <div className="w-9 h-9 rounded-lg bg-[#ECFDF3] text-[#12B76A] flex items-center justify-center shrink-0">
            <Video className="w-4 h-4" />
          </div>
          <div>
            <div className="text-[11px] font-medium text-[#667085]">Active Calls</div>
            <div className="text-base font-bold text-[#12B76A]">
              {stats?.activeMeetingsCount ?? 1} Live
            </div>
          </div>
        </Card>

        <Card className="p-3.5 flex items-center gap-3">
          <div className="w-9 h-9 rounded-lg bg-[#FFF6ED] text-[#F79009] flex items-center justify-center shrink-0">
            <ListTodo className="w-4 h-4" />
          </div>
          <div>
            <div className="text-[11px] font-medium text-[#667085]">Pending Tasks</div>
            <div className="text-base font-bold text-[#F79009]">
              {stats?.pendingTasksCount ?? 4}
            </div>
          </div>
        </Card>

        <Card className="p-3.5 flex items-center gap-3">
          <div className="w-9 h-9 rounded-lg bg-[#F8FAFC] text-[#344054] flex items-center justify-center shrink-0">
            <HardDrive className="w-4 h-4" />
          </div>
          <div>
            <div className="text-[11px] font-medium text-[#667085]">Cloud Storage</div>
            <div className="text-base font-bold text-[#101828]">
              {stats?.storageUsedGb ?? 1.4} / {stats?.storageLimitGb ?? 25} GB
            </div>
          </div>
        </Card>
      </div>

      {/* Navigation Tabs */}
      <Tabs
        activeTab={activeTab}
        onChange={(id) => setActiveTab(id as any)}
        tabs={[
          { id: 'members', label: 'Team Members', icon: <Users className="w-4 h-4" /> },
          { id: 'activity', label: 'Team Activity', icon: <Activity className="w-4 h-4" /> },
          { id: 'settings', label: 'Workspace Settings', icon: <Settings className="w-4 h-4" /> },
        ]}
      />

      {/* TAB 1: MEMBERS LIST & ROLE MANAGEMENT */}
      {activeTab === 'members' && (
        <div className="space-y-4">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div className="relative w-full sm:w-72">
              <Search className="w-3.5 h-3.5 text-[#98A2B3] absolute left-3 top-1/2 -translate-y-1/2" />
              <input
                type="text"
                placeholder="Search by name or email..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-9 pr-3 py-1.5 rounded-lg border border-[#D0D5DD] bg-white text-xs text-[#101828] placeholder-[#98A2B3] focus:outline-none focus:border-[#2563EB]"
              />
            </div>
            <div className="text-xs text-[#667085] font-medium">
              {filteredMembers.length} members enrolled
            </div>
          </div>

          <Card padding="none" className="overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-left text-xs">
                <thead className="bg-[#F8FAFC] border-b border-[#EAECF0] text-[#667085] uppercase tracking-wider text-[10px] font-semibold">
                  <tr>
                    <th className="py-3 px-4">Member</th>
                    <th className="py-3 px-4">Role</th>
                    <th className="py-3 px-4">Status</th>
                    <th className="py-3 px-4 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#EAECF0]">
                  {filteredMembers.length === 0 ? (
                    <tr>
                      <td colSpan={4} className="py-8 text-center text-xs text-[#667085]">
                        No team members found.
                      </td>
                    </tr>
                  ) : (
                    filteredMembers.map((member) => {
                      const u = member.userId || {}
                      const isOwner = member.role === 'owner'
                      return (
                        <tr key={member._id || member.id} className="hover:bg-[#F8FAFC] transition-colors">
                          <td className="py-3 px-4 flex items-center gap-3">
                            <img
                              src={
                                u.avatarUrl ||
                                'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=120&h=120&q=80'
                              }
                              alt={u.name || 'Member'}
                              className="w-8 h-8 rounded-full object-cover ring-1 ring-[#EAECF0]"
                            />
                            <div>
                              <div className="font-semibold text-[#101828]">{u.name || 'Team Colleague'}</div>
                              <div className="text-[11px] text-[#667085]">{u.email}</div>
                            </div>
                          </td>
                          <td className="py-3 px-4">
                            <Badge
                              variant={
                                member.role === 'owner'
                                  ? 'navy'
                                  : member.role === 'admin'
                                  ? 'primary'
                                  : 'gray'
                              }
                              size="sm"
                            >
                              {member.role.toUpperCase()}
                            </Badge>
                          </td>
                          <td className="py-3 px-4">
                            <span className="inline-flex items-center gap-1 font-medium text-[#12B76A]">
                              <span className="w-1.5 h-1.5 rounded-full bg-[#12B76A]" />
                              Active
                            </span>
                          </td>
                          <td className="py-3 px-4 text-right">
                            <div className="flex items-center justify-end gap-2">
                              {!isOwner && (
                                <>
                                  <Button
                                    variant="outline"
                                    size="sm"
                                    onClick={() => handleOpenRoleModal(member)}
                                  >
                                    Change Role
                                  </Button>
                                  <button
                                    onClick={() => handleRemoveMember(member._id || member.id || '')}
                                    className="p-1.5 rounded-lg text-[#F04438] hover:bg-[#FEE4E2] transition-colors"
                                    title="Remove member"
                                  >
                                    <Trash2 className="w-3.5 h-3.5" />
                                  </button>
                                </>
                              )}
                            </div>
                          </td>
                        </tr>
                      )
                    })
                  )}
                </tbody>
              </table>
            </div>
          </Card>
        </div>
      )}

      {/* TAB 2: TEAM ACTIVITY FEED */}
      {activeTab === 'activity' && (
        <Card className="space-y-4">
          <div className="flex items-center justify-between border-b border-[#EAECF0] pb-3">
            <div>
              <h3 className="font-heading font-semibold text-sm text-[#101828]">
                Recent Workspace Activity
              </h3>
              <p className="text-xs text-[#667085]">
                Audit log of completed meetings, member invitations, and action items.
              </p>
            </div>
            <Badge variant="primary" size="sm">
              Live Stream
            </Badge>
          </div>

          <div className="space-y-3">
            {activities.map((act) => (
              <div
                key={act.id}
                className="p-3.5 rounded-xl border border-[#EAECF0] bg-[#F8FAFC] flex items-start gap-3.5 text-xs"
              >
                <div className="w-8 h-8 rounded-lg bg-[#EFF8FF] text-[#2563EB] flex items-center justify-center shrink-0 mt-0.5">
                  <Activity className="w-4 h-4" />
                </div>
                <div className="space-y-1 flex-1">
                  <div className="flex items-center justify-between">
                    <span className="font-semibold text-[#101828]">{act.title}</span>
                    <span className="text-[10px] text-[#98A2B3]">{act.timestamp}</span>
                  </div>
                  <p className="text-xs text-[#475467]">{act.details}</p>
                  <div className="text-[10px] text-[#2563EB] font-medium">Actor: {act.actorName}</div>
                </div>
              </div>
            ))}
          </div>
        </Card>
      )}

      {/* TAB 3: WORKSPACE SETTINGS */}
      {activeTab === 'settings' && (
        <Card className="space-y-6">
          <div className="border-b border-[#EAECF0] pb-4">
            <h3 className="font-heading font-semibold text-sm text-[#101828]">
              Workspace Configuration
            </h3>
            <p className="text-xs text-[#667085]">
              Update workspace identification, custom URL slug, and access privacy.
            </p>
          </div>

          {settingsSaved && (
            <div className="p-3 bg-[#ECFDF3] border border-[#A6F4C5] rounded-xl text-xs text-[#027A48] flex items-center gap-2">
              <CheckCircle2 className="w-4 h-4" />
              <span>Workspace settings saved successfully.</span>
            </div>
          )}

          <form onSubmit={handleSaveSettings} className="space-y-4">
            <Input
              label="Workspace Name"
              value={wsName}
              onChange={(e) => setWsName(e.target.value)}
              required
            />

            <Input
              label="Workspace URL Slug"
              value={wsSlug}
              onChange={(e) => setWsSlug(e.target.value)}
              required
            />

            <div className="space-y-1.5 text-left">
              <label className="block text-xs font-medium text-[#344054]">
                Description
              </label>
              <textarea
                value={wsDescription}
                onChange={(e) => setWsDescription(e.target.value)}
                rows={3}
                className="w-full rounded-lg border border-[#D0D5DD] bg-white px-3 py-2 text-xs text-[#101828] focus:border-[#2563EB] focus:outline-none"
              />
            </div>

            <div className="p-3.5 rounded-xl border border-[#EAECF0] bg-[#F8FAFC] flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 rounded-lg bg-white border border-[#D0D5DD] flex items-center justify-center text-[#2563EB]">
                  {wsIsPrivate ? <Lock className="w-4 h-4" /> : <Globe className="w-4 h-4" />}
                </div>
                <div>
                  <div className="font-semibold text-xs text-[#101828]">Private Workspace</div>
                  <div className="text-[11px] text-[#667085]">
                    Require explicit invitations to view meetings and chat history
                  </div>
                </div>
              </div>
              <input
                type="checkbox"
                checked={wsIsPrivate}
                onChange={(e) => setWsIsPrivate(e.target.checked)}
                className="rounded border-[#D0D5DD] text-[#2563EB] w-4 h-4"
              />
            </div>

            <div className="flex justify-end pt-2">
              <Button
                type="submit"
                variant="primary"
                size="sm"
                disabled={isSavingSettings}
                icon={
                  isSavingSettings ? (
                    <Loader2 className="w-3.5 h-3.5 animate-spin" />
                  ) : (
                    <Save className="w-3.5 h-3.5" />
                  )
                }
              >
                {isSavingSettings ? 'Saving...' : 'Save Settings'}
              </Button>
            </div>
          </form>
        </Card>
      )}

      {/* Invite Member Modal */}
      <Modal
        isOpen={inviteModalOpen}
        onClose={() => setInviteModalOpen(false)}
        title="Invite New Colleague"
        description="Send an invitation to join this workspace."
      >
        <form onSubmit={handleSendInvite} className="space-y-4 pt-2">
          <Input
            label="Email Address"
            type="email"
            placeholder="colleague@company.com"
            value={inviteEmail}
            onChange={(e) => setInviteEmail(e.target.value)}
            required
            autoFocus
          />

          <div className="space-y-1.5 text-left">
            <label className="block text-xs font-medium text-[#344054]">Workspace Role</label>
            <select
              value={inviteRole}
              onChange={(e) => setInviteRole(e.target.value as any)}
              className="w-full rounded-lg border border-[#D0D5DD] bg-white px-3 py-2 text-xs text-[#101828] focus:border-[#2563EB] focus:outline-none"
            >
              <option value="member">Member (Can host & join meetings)</option>
              <option value="admin">Admin (Can manage workspace settings)</option>
              <option value="guest">Guest (Can join assigned rooms only)</option>
            </select>
          </div>

          <div className="flex justify-end gap-2 pt-2">
            <Button
              type="button"
              variant="secondary"
              size="sm"
              onClick={() => setInviteModalOpen(false)}
            >
              Cancel
            </Button>
            <Button type="submit" variant="primary" size="sm" disabled={isInviting}>
              {isInviting ? 'Inviting...' : 'Send Invitation'}
            </Button>
          </div>
        </form>
      </Modal>

      {/* Change Role Modal */}
      {selectedMember && (
        <Modal
          isOpen={roleModalOpen}
          onClose={() => setRoleModalOpen(false)}
          title="Change Member Role"
          description={`Update permissions for ${selectedMember.userId?.name || 'User'}`}
        >
          <div className="space-y-4 pt-2 text-xs">
            <div className="space-y-1.5 text-left">
              <label className="block text-xs font-medium text-[#344054]">Select Role</label>
              <select
                value={targetRole}
                onChange={(e) => setTargetRole(e.target.value as any)}
                className="w-full rounded-lg border border-[#D0D5DD] bg-white px-3 py-2 text-xs text-[#101828] focus:border-[#2563EB] focus:outline-none"
              >
                <option value="member">Member</option>
                <option value="admin">Admin</option>
                <option value="guest">Guest</option>
              </select>
            </div>

            <div className="flex justify-end gap-2 pt-2">
              <Button
                type="button"
                variant="secondary"
                size="sm"
                onClick={() => setRoleModalOpen(false)}
              >
                Cancel
              </Button>
              <Button type="button" variant="primary" size="sm" onClick={handleSaveRole}>
                Update Role
              </Button>
            </div>
          </div>
        </Modal>
      )}
    </div>
  )
}

