export const inviteMember = async (req: Request, res: Response): Promise<void> => {
  const { id: workspaceId } = req.params
  const { email, role = 'member' } = req.body

  if (db.isConnected()) {
    try {
      let user = await User.findOne({ email })
      if (!user) {
        user = await User.create({
          name: email.split('@')[0],
          email,
          role: 'guest',
          status: 'away',
        })
      }

      const member = await WorkspaceMember.findOneAndUpdate(
        { workspaceId, userId: user._id },
        { role, joinedAt: new Date() },
        { upsert: true, new: true }
      )

      ApiResponse.created(res, member, `Invitation sent to ${email}.`)
      return
    } catch {}
  }

  const newMem = {
    _id: `mem_${Date.now()}`,
    id: `mem_${Date.now()}`,
    workspaceId,
    role,
    status: 'invited',
    userId: {
      name: email.split('@')[0],
      email,
      status: 'invited',
      avatarUrl: 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=120&h=120&q=80',
    },
    joinedAt: new Date(),
  }
  inMemoryMembers.push(newMem)

  ApiResponse.created(res, newMem, `Invitation sent to ${email}.`)
}

export const updateMemberRole = async (req: Request, res: Response): Promise<void> => {
  const { id: workspaceId, memberId } = req.params
  const { role } = req.body

  if (db.isConnected()) {
    try {
      const updated = await WorkspaceMember.findByIdAndUpdate(memberId, { role }, { new: true })
      if (updated) {
        ApiResponse.success(res, updated, 'Member role updated.')
        return
      }
    } catch {}
  }

  const item = inMemoryMembers.find((m) => m._id === memberId || m.id === memberId)
  if (item) {
    item.role = role
    ApiResponse.success(res, item, 'Member role updated.')
    return
  }

  ApiResponse.success(res, { memberId, role }, 'Member role updated.')
}

export const removeMember = async (req: Request, res: Response): Promise<void> => {
  const { id: workspaceId, memberId } = req.params

  if (db.isConnected()) {
    try {
      await WorkspaceMember.findByIdAndDelete(memberId)
    } catch {}
  }

  const idx = inMemoryMembers.findIndex((m) => m._id === memberId || m.id === memberId)
  if (idx !== -1) {
    inMemoryMembers.splice(idx, 1)
  }

  ApiResponse.success(res, { removed: true, memberId }, 'Member removed from workspace.')
}

import http from 'http'
import express, { Express } from 'express'
import cors from 'cors'
import helmet from 'helmet'
import compression from 'compression'
import cookieParser from 'cookie-parser'
import { env } from './config/env'
import { corsOptions } from './config/cors'
import { db } from './config/db'
import { logger } from './utils/logger'
import { requestLogger } from './middleware/requestLogger.middleware'
import { errorHandler, notFoundHandler } from './middleware/errorHandler.middleware'
import { apiRateLimiter } from './middleware/rateLimiter.middleware'
import { mongoSanitize } from './middleware/sanitize.middleware'
import rootRouter from './routes'
import { getHealth } from './controllers/health.controller'
import { initSocketServer } from './sockets/socketHandler'

export const createApp = (): { app: Express; server: http.Server } => {
  const app = express()
  const server = http.createServer(app)

  // Security & Utility Middleware
  app.use(helmet({ crossOriginResourcePolicy: false }))
  app.use(cors(corsOptions))
  app.use(cookieParser(env.COOKIE_SECRET))
  app.use(compression())
  app.use(express.json({ limit: '10mb' }))
  app.use(express.urlencoded({ extended: true, limit: '10mb' }))
  app.use(mongoSanitize)
  app.use(requestLogger)

  // Root welcome & status
  app.get('/', (req, res) => {
    res.json({
      service: 'IntellMeet Enterprise Collaboration Engine',
      version: '1.0.0',
      status: 'active',
      endpoints: {
        health: '/health',
        apiHealth: '/api/v1/health',
        meetings: '/api/v1/meetings',
        aiSummaries: '/api/v1/ai/summarize',
      },
    })
  })

  // Direct top-level health check endpoint for cloud load balancers & orchestrators
  app.get('/health', getHealth)

  // API Routes with rate limiting
  app.use('/api', apiRateLimiter, rootRouter)

  // 404 & Centralized Error Handler
  app.use(notFoundHandler)
  app.use(errorHandler)

  // Socket.io initialization
  initSocketServer(server)

  return { app, server }
}

export const startServer = async (): Promise<http.Server> => {
  const { server } = createApp()

  // Listen on PORT immediately so cloud load balancers & health checks pass without delay
  const port = env.PORT || 5000
  server.listen(port, '0.0.0.0', () => {
    logger.info(`🚀 IntellMeet Server running at http://0.0.0.0:${port}`)
    logger.info(`📡 Real-time Socket.io signaling active on port ${port}`)
    logger.info(`🩺 Health check accessible at http://0.0.0.0:${port}/api/v1/health`)
  })

  // Connect to Database
  try {
    await db.connect()
  } catch (err: any) {
    logger.error('Database connection failed during startup.', {
      errorType: err instanceof Error ? err.name : 'UnknownError',
    })
  }

  // Graceful shutdown
  const handleShutdown = async (signal: string) => {
    logger.info(`Received ${signal}. Gracefully shutting down IntellMeet server...`)
    server.close(async () => {
      await db.disconnect()
      logger.info('IntellMeet server terminated gracefully.')
      process.exit(0)
    })
  }

  process.on('SIGTERM', () => handleShutdown('SIGTERM'))
  process.on('SIGINT', () => handleShutdown('SIGINT'))

  return server
}

// Start when executed directly
const isDirectExecution =
  Boolean(typeof require !== 'undefined' && require.main === module) ||
  Boolean(process.argv[1] && /[/\\](?:src[/\\])?index\.(ts|js)$/.test(process.argv[1]))

if (isDirectExecution) {
  startServer().catch((err) => {
    logger.error('Fatal error during server startup.', {
      errorType: err instanceof Error ? err.name : 'UnknownError',
    })
    process.exit(1)
  })
}

import { Request, Response, NextFunction } from 'express'
import { AppError } from '../utils/appError'
import { verifyAccessToken, TokenPayload } from '../utils/token'
import { WorkspaceMember } from '../models/WorkspaceMember.model'

// Extend Express Request
declare global {
  namespace Express {
    interface Request {
      user?: TokenPayload
    }
  }
}

export const authenticate = (
  req: Request,
  res: Response,
  next: NextFunction
): void => {
  let token: string | undefined

  // 1. Check Authorization header
  if (
    req.headers.authorization &&
    req.headers.authorization.startsWith('Bearer ')
  ) {
    token = req.headers.authorization.split(' ')[1]
  } else if (req.cookies?.accessToken) {
    // 2. Check cookies
    token = req.cookies.accessToken
  }

  if (!token) {
    return next(AppError.unauthorized('Authentication token is required'))
  }

  try {
    const decoded = verifyAccessToken(token)
    req.user = decoded
    next()
  } catch (err: unknown) {
    const error = err as Error
    if (error.name === 'TokenExpiredError') {
      return next(AppError.unauthorized('Session has expired. Please log in again.'))
    }
    return next(AppError.unauthorized('Invalid authentication token'))
  }
}

export const authenticateOptional = (
  req: Request,
  res: Response,
  next: NextFunction
): void => {
  let token: string | undefined

  if (
    req.headers.authorization &&
    req.headers.authorization.startsWith('Bearer ')
  ) {
    token = req.headers.authorization.split(' ')[1]
  } else if (req.cookies?.accessToken) {
    token = req.cookies.accessToken
  }

  if (token) {
    try {
      const decoded = verifyAccessToken(token)
      req.user = decoded
    } catch {
      // Ignore token decode failure for optional auth
    }
  }

  next()
}

export const requireRole = (...allowedRoles: string[]) => {
  return (req: Request, res: Response, next: NextFunction): void => {
    if (!req.user) {
      return next(AppError.unauthorized('Authentication required'))
    }

    if (!allowedRoles.includes(req.user.role)) {
      return next(
        AppError.forbidden(
          `Access denied. Role "${req.user.role}" does not have sufficient permissions.`
        )
      )
    }

    next()
  }
}

export const requireWorkspaceRole = (...allowedRoles: string[]) => {
  return async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    if (!req.user) {
      return next(AppError.unauthorized('Authentication required'))
    }

    const workspaceId = req.params.workspaceId || req.body.workspaceId || req.user.workspaceId
    if (!workspaceId) {
      return next(AppError.badRequest('Workspace ID is required for verification'))
    }

    // Super admins bypass workspace check
    if (req.user.role === 'super_admin' || req.user.role === 'org_admin') {
      return next()
    }

    try {
      const membership = await WorkspaceMember.findOne({
        workspaceId,
        userId: req.user.userId,
      })

      if (!membership || !allowedRoles.includes(membership.role)) {
        return next(
          AppError.forbidden(
            'You do not possess the required permissions in this workspace.'
          )
        )
      }

      next()
    } catch (err) {
      next(err)
    }
  }
}

import { Request, Response, NextFunction } from 'express'

function sanitizeObject(obj: any): void {
  if (!obj || typeof obj !== 'object') return

  for (const key of Object.keys(obj)) {
    if (key.startsWith('$') || key.includes('.')) {
      delete obj[key]
    } else if (typeof obj[key] === 'object') {
      sanitizeObject(obj[key])
    }
  }
}

export const mongoSanitize = (req: Request, res: Response, next: NextFunction): void => {
  if (req.body) sanitizeObject(req.body)
  if (req.query) sanitizeObject(req.query)
  if (req.params) sanitizeObject(req.params)
  next()
}

