export class NotificationService {
  /**
   * Creates a notification, saves to database (or in-memory store), and broadcasts via Socket.io
   */
  public static async createNotification(input: CreateNotificationInput): Promise<any> {
    const formatted = {
      ...input,
      read: false,
      createdAt: new Date(),
      updatedAt: new Date(),
    }

    let savedNotif: any = null

    if (db.isConnected()) {
      try {
        savedNotif = await Notification.create(formatted)
      } catch (err) {
        logger.warn('Failed to save notification to MongoDB, using memory fallback:', err)
      }
    }

    if (!savedNotif) {
      savedNotif = {
        _id: `notif_${Date.now()}_${Math.random().toString(36).substr(2, 5)}`,
        id: `notif_${Date.now()}`,
        ...formatted,
      }
      inMemoryNotifications.unshift(savedNotif)
    }

    // Broadcast in real-time via Socket.io
    const io = getSocketServer()
    if (io) {
      io.emit('notification', savedNotif)
      logger.info(`🔔 [Notification Broadcast] ${input.type}: "${input.title}"`)
    }

    return savedNotif
  }

  public static async getNotificationsForUser(recipientId?: string): Promise<any[]> {
    if (db.isConnected() && recipientId) {
      try {
        const list = await Notification.find({ recipientId }).sort({ createdAt: -1 }).limit(30).lean()
        if (list && list.length > 0) return list
      } catch (err) {
        logger.warn('Failed querying notifications from MongoDB:', err)
      }
    }

    return inMemoryNotifications
  }

  public static async markRead(id: string): Promise<any> {
    if (db.isConnected()) {
      try {
        const updated = await Notification.findByIdAndUpdate(
          id,
          { $set: { read: true, readAt: new Date() } },
          { new: true }
        )
        if (updated) return updated
      } catch {}
    }

    const item = inMemoryNotifications.find((n) => n._id === id || n.id === id)
    if (item) {
      item.read = true
      item.readAt = new Date()
      return item
    }

    return { id, read: true }
  }

  public static async markAllRead(recipientId?: string): Promise<void> {
    if (db.isConnected() && recipientId) {
      try {
        await Notification.updateMany({ recipientId, read: false }, { $set: { read: true, readAt: new Date() } })
      } catch {}
    }

    for (const n of inMemoryNotifications) {
      n.read = true
      n.readAt = new Date()
    }
  }
}

import { AccessToken } from 'livekit-server-sdk'
import { env } from '../config/env'
import { logger } from '../utils/logger'

export interface SfuCredentials {
  provider: 'livekit' | 'webrtc_mesh'
  livekitUrl: string
  token: string
  iceServers: RTCIceServer[]
  roomId: string
  identity: string
  isHost: boolean
}

export class SfuService {
  /**
   * Generates a signed LiveKit SFU access token and ICE server configuration
   */
  public static async generateToken(params: {
    roomId: string
    identity: string
    name: string
    isHost?: boolean
  }): Promise<SfuCredentials> {
    const { roomId, identity, name, isHost = false } = params

    // 1. Generate LiveKit Access Token
    const at = new AccessToken(env.LIVEKIT_API_KEY, env.LIVEKIT_API_SECRET, {
      identity,
      name,
      ttl: '4h',
    })

    at.addGrant({
      roomJoin: true,
      room: roomId,
      canPublish: true,
      canSubscribe: true,
      canPublishData: true,
      roomAdmin: isHost,
      roomRecord: isHost,
    })

    const token = await at.toJwt()

    // 2. Assemble STUN/TURN ICE Servers
    const iceServers: RTCIceServer[] = env.STUN_SERVERS.split(',')
      .map((url) => url.trim())
      .filter(Boolean)
      .map((url) => ({ urls: url }))

    if (env.TURN_SERVERS) {
      const turnUrls = env.TURN_SERVERS.split(',').map((u) => u.trim()).filter(Boolean)
      const turnConfig: RTCIceServer = {
        urls: turnUrls,
      }
      if (env.TURN_USERNAME) turnConfig.username = env.TURN_USERNAME
      if (env.TURN_CREDENTIAL) turnConfig.credential = env.TURN_CREDENTIAL
      iceServers.push(turnConfig)
    }

    logger.info(`🔑 Generated SFU token for ${identity} (${name}) in room: ${roomId} [Host: ${isHost}]`)

    return {
      provider: 'livekit',
      livekitUrl: env.LIVEKIT_URL,
      token,
      iceServers,
      roomId,
      identity,
      isHost,
    }
  }

  /**
   * Get raw ICE servers list for standard WebRTC mesh
   */
  public static getIceServers(): RTCIceServer[] {
    const iceServers: RTCIceServer[] = env.STUN_SERVERS.split(',')
      .map((url) => url.trim())
      .filter(Boolean)
      .map((url) => ({ urls: url }))

    if (env.TURN_SERVERS) {
      const turnConfig: RTCIceServer = {
        urls: env.TURN_SERVERS.split(',').map((u) => u.trim()).filter(Boolean),
      }
      if (env.TURN_USERNAME) turnConfig.username = env.TURN_USERNAME
      if (env.TURN_CREDENTIAL) turnConfig.credential = env.TURN_CREDENTIAL
      iceServers.push(turnConfig)
    }

    return iceServers
  }
}

import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3'
import path from 'path'
import fs from 'fs'
import { env } from '../config/env'
import { logger } from '../utils/logger'
import { Recording, IRecordingDocument } from '../models/Recording.model'
import { db } from '../config/db'

export interface UploadRecordingOptions {
  meetingId: string
  title: string
  durationSeconds: number
  buffer: Buffer
  mimeType: string
  format?: 'mp4' | 'webm'
}

export class StorageService {
  private static s3Client: S3Client | null = null

  private static getClient(): S3Client | null {
    if (this.s3Client) return this.s3Client

    if (env.S3_ACCESS_KEY_ID && env.S3_SECRET_ACCESS_KEY) {
      this.s3Client = new S3Client({
        region: env.S3_REGION || 'auto',
        endpoint: env.S3_ENDPOINT || undefined,
        credentials: {
          accessKeyId: env.S3_ACCESS_KEY_ID,
          secretAccessKey: env.S3_SECRET_ACCESS_KEY,
        },
        forcePathStyle: true,
      })
      logger.info('☁️ Cloudflare R2 / S3 persistent storage client initialized.')
      return this.s3Client
    }

    return null
  }

  /**
   * Uploads recorded audio/video buffer to persistent S3 / Cloudflare R2 storage
   * and persists metadata in MongoDB.
   */
  public static async uploadRecording(
    options: UploadRecordingOptions
  ): Promise<any> {
    const { meetingId, title, durationSeconds, buffer, mimeType, format = 'webm' } = options
    const key = `recordings/${meetingId}/${Date.now()}.${format}`
    let publicUrl = `${env.S3_PUBLIC_URL}/${key}`

    const client = this.getClient()

    if (client) {
      // 1. Upload to Cloudflare R2 / AWS S3
      await client.send(
        new PutObjectCommand({
          Bucket: env.S3_BUCKET_NAME,
          Key: key,
          Body: buffer,
          ContentType: mimeType,
          Metadata: {
            meetingId,
            duration: String(durationSeconds),
          },
        })
      )
      logger.info(`📼 [Storage] Uploaded recording to S3/R2: ${key} (${buffer.length} bytes)`)
    } else {
      // Offline/Dev fallback: ensure persistent directory storage
      const uploadDir = path.resolve(process.cwd(), 'uploads', 'recordings', meetingId)
      if (!fs.existsSync(uploadDir)) {
        fs.mkdirSync(uploadDir, { recursive: true })
      }
      const localFilePath = path.join(uploadDir, `${Date.now()}.${format}`)
      fs.writeFileSync(localFilePath, buffer)
      publicUrl = `/uploads/recordings/${meetingId}/${path.basename(localFilePath)}`
      logger.info(`📼 [Storage] Persisted recording to storage: ${localFilePath} (${buffer.length} bytes)`)
    }

    // 2. Persist recording record in MongoDB
    if (db.isConnected()) {
      const record = await Recording.create({
        meetingId,
        title,
        url: publicUrl,
        durationSeconds,
        fileSize: buffer.length,
        format,
        status: 'ready',
      })
      return record
    }

    return {
      _id: `rec_${Date.now()}`,
      meetingId,
      title,
      url: publicUrl,
      durationSeconds,
      fileSize: buffer.length,
      format,
      status: 'ready',
      createdAt: new Date(),
    }
  }
}

import jwt from 'jsonwebtoken'
import bcrypt from 'bcryptjs'
import { env } from '../config/env'

export interface TokenPayload {
  userId: string
  email: string
  role: string
  organizationId?: string
  workspaceId?: string
}

export interface GeneratedTokens {
  accessToken: string
  refreshToken: string
}

export const hashPassword = async (password: string): Promise<string> => {
  const salt = await bcrypt.genSalt(10)
  return bcrypt.hash(password, salt)
}

export const comparePassword = async (
  password: string,
  hashed: string
): Promise<boolean> => {
  return bcrypt.compare(password, hashed)
}

export const generateAccessToken = (payload: TokenPayload): string => {
  return jwt.sign(payload, env.JWT_SECRET, {
    expiresIn: env.JWT_EXPIRES_IN as any,
  })
}

export const generateTokens = (payload: TokenPayload): GeneratedTokens => {
  const accessToken = generateAccessToken(payload)

  const refreshToken = jwt.sign(payload, env.JWT_REFRESH_SECRET, {
    expiresIn: env.JWT_REFRESH_EXPIRES_IN as any,
  })

  return { accessToken, refreshToken }
}

export const verifyAccessToken = (token: string): TokenPayload => {
  return jwt.verify(token, env.JWT_SECRET) as TokenPayload
}

export const verifyRefreshToken = (token: string): TokenPayload => {
  return jwt.verify(token, env.JWT_REFRESH_SECRET) as TokenPayload
}

